COLLDATA("tadabburur","ur",[[127,"§المائدہ\ndeeds\nآج باربار یہ دعاپڑھئے۔‘‘اَللّٰہُمَّ ارْزُقْنِیْ وَأَنْتَ خَیرُ الرَّازِقِینَ’’ اے اللہ !مجھے رزق دے بیشک تو بہترین رزق دینے والا ہے۔جیسے کہ آپ سے پہلے انبیاء یہ دعا مانگتے تھے.\nآج رات باربار یہ آیت پڑھئے او ر اس کے معانی پر خوب غور کیجئے جیسا نبی صلی اللہ علیہ وسلم نے کیا ہے.\nاللہ تعالیٰ سے دعا مانگئے کہ آپ کو اپنے قول وعمل میں سچا بنادے.\nguid\nایسا نہ کیجئے کہ آپ اللہ تعالیٰ سے کوئی وعدہ کرکے کچھ مانگیں پھر وہ آپ کی مراد پوری کردے تو آپ وعدہ توڑدیں ۔کیونکہ ایسا کرنا سخت عذاب کی وجہ بن سکتا ہے.\nاللہ سبحانہ وتعالیٰ سے کچھ مانگتے ہوئے ادب اور احترام کا مظاہرہ کرنا بندے کے ایمان کی نشانی ہے.\nسچائی کی فضیلت بیان ہوتی ہے اور سچ بولنا یقیناً دنیا اور آخرت دونوں جگہ فائدہ پہونچاتا ہے.\nrefl\nقَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ١١٥\nعبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں : ‘‘قیامت کے دن سب سے سخت عذاب ان لوگوں کو ہوگا جنہوں نے آسمانی دسترخوان نازل کرنے کا مطالبہ کیا اور پھر اس کے نازل ہونے کے بعدکفر کیا ۔اسی طرح آل فرعون اور منافقین کو بھی سخت عذاب دیاجائے گا’’۔(ابن جزی: ۱؍۲۵۸)\nحجت ودلیل کے واضح ہوجانے کے بعد نافرمانی کرنا ، دلیل واضح نہ ہونے سے پہلے یا ابتداءً نافرمانی کرنے سے زیادہ سخت گناہ ہے۔ اس کی وضاحت کیجئے.\nوَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ ١١٦\n(إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ ) اگر میں نے یہ بات کہی ہوتی تو تجھے اس کا علم ضرور ہوتا۔ عیسیٰ علیہ السلام کی یہ بات اللہ کی بارگاہ میں اپنی بے گناہی کا عذر پیش کرنے کی خاطر ہے اور خود کو اور اپنی والدہ کو معبود بنالینے کی بات کے تعلق سے اپنی براءت کے اظہار کے لئے ہے۔ اور عیسیٰ علیہ السلام نے اپنی براءت و بے گناہی کو ظاہر کرنے کے لئےعلم کو اللہ کے حوالے کیا ہےکیونکہ اللہ تعالیٰ تو بخوبی جانتا ہی ہے کہ عیسیٰ علیہ السلام نے یہ بات نہیں کہی ہے۔ (ابن جزی: ۱؍ ۲۵۹)\nاس آیت میں عیسیٰ علیہ السلام کااپنے رب کے ساتھ ادب وتعظیم کو تین پوائنٹ میں بیان کیجئے.\nوَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ\nعیسیٰ علیہ السلام نےجواب دینے سے پہلے اللہ کی تسبیح اور پاکی سےاپنی بات شروع کیا ہے۔اس کی دووجہیں ہیں:اول: یہ کہ الوہیت و عبادت وغیرہ میں اللہ تعالیٰ کو شرکت غیر سے پاک کرنے کےلئے ۔دوم : اللہ کی عزت وعظمت کے سامنے عاجزی وانکساری اختیار کرنے کے لئے اور اس کے غلبہ ودبدبہ سے خوف کھانے کے لئے ۔ (القرطبی: ۸؍۳۰۲)\nعیسیٰ علیہ السلام نے اپنے جواب کی شروعات اللہ تعالیٰ کی تسبیح سے کیوں کی ہے؟ ان کے اس انداز سے ہمیں کیا سبق ملتا ہے؟\nإِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ\nیہاں نفس یعنی جی اور دل کو خاص طور پر ذکر کیا گیا ہے کیونکہ نفس ہی وہ جگہ ہے جہاں بات کو چھپائے رکھنے اور معلومات کو جمع رکھنے کا امکان ہے۔ (ابن عطیہ: ۲؍ ۲۶۳)\nآیت میں ‘‘نفس’’ کو خاص طور پر ذکر کرنے کی کیا وجہ ہے؟\nإِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ١١٨\nیہاں اللہ تعالیٰ کو (ٱلۡعَزِيزُ ٱلۡحَكِيمُ) غالب اور دانا کہا۔ ‘‘اَلْغَفُوْرُ الرَّحِیْمُ’’ بہت بخشنے والا،بڑا رحم کرنے والا نہیں کہا ۔ یہ اللہ ذوالجلال والاکرام کے حضور میں انتہا درجہ کا ادب ہے کیونکہ عیسیٰ علیہ السلام نے یہ بات ان لوگوں پراللہ تعالیٰ کے سخت غضبناک اور ناراض ہونے نیز انہیں جہنم میں ڈال دینے کا حکم دیتے وقت کہی ۔لہذا یہ رحم ومہربانی طلب کرنے اور سفارش کرنے کا موقع نہیں ہے بلکہ یہ تو ان لوگوں سے بَراء ت اور لاتعلقی کے اظہار کا موقع ہے۔ چنانچہ مطلب یہ ہواکہ: اگر تو انہیں معاف کردے ،بخش دے تو تیری بخشش تیری قدرت اور علم کامل ہونے کی بناپر ہوگی۔ اس وجہ سے نہیں کہ تو ان سے انتقام لینے یا سزا دینے سے عاجز ہے اور نہ ہی اس وجہ سے کہ ان کے جرائم اور گناہوں کی مقدارتجھ سے پوشیدہ اور چھپی ہوئی ہے ۔ (ابن القیم: ۱؍ ۳۳۷)\nآیت میں (ٱلۡعَزِيزُ ٱلۡحَكِيمُ) کیوں فرمایا؟ ‘‘ٱلۡعَزِيزُ ٱلۡحَكِيمُ’’ کیوں نہیں ؟\nقَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١١٩\n(قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ) اللہ فرمائیگا: آج وہ دن ہے کہ سچے انسانوں کو ان کی سچائی (ہی) کام آئیگی ۔ یہ فرمان تمام سچے لوگوں کے حق میں عام ہے ۔ سارے سچے لوگ اس سے مراد ہیں اور عیسیٰ علیہ السلام خصوصی طور پر اس میں شامل ہیں کیونکہ اس میں عیسیٰ علیہ السلام کے اس کلام کی سچائی کی طرف اشارہ ہے جسے اللہ تعالیٰ نے ان کی طرف سے نقل فرمایا ہے۔ (ابن جزی: ۱؍ ۲۶۰)\nاس آیت میں سچائی کی فضیلت کے پہلو کو بیان کیجئے\nقَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ\nاس عبارت کے معنی میں اللہ تعالیٰ پر ایمان رکھنے والا ہرشخص داخل ہے اور جو آدمی جتنا زیادہ پرہیزگار اور تقویٰ والا ہوگا وہ اس عبارت کے معنی میں اتنا زیادہ داخل ہوگا ۔ پھر یہ عبارت عیسیٰ علیہ السلام کے قیامت کے دن کے حال اور ان کی کہی ہوئی بات کے سچ ہونے کی طرف اشارہ بھی کرتی ہے ۔ چنانچہ اس کی وجہ سے عیسیٰ علیہ السلام کو میدان محشرمیں عظیم شرف حاصل ہوگا۔اگرچہ الفاظ عیسیٰ علیہ السلام اور ان کے علاوہ دوسروں کو بھی اپنے مضمون میں شامل کئے ہوئے ہیں۔ (ابن عطیہ: ۲؍ ۲۶۳)\nسچائی میں دنیا اور آخرت کی نجات ہے ۔یہ بات آیت کی روشنی میں واضح کیجئے.\nwords\nتَكُونُ لَنَا عِيدًااس کھانا نازل ہونے کے دن کو عید بنالیں اس کی تعظیم کریں؛ ہم بھی ہمارے بعد والے بھی.\nوَآيَةً مِنكَاور وہ آپ کی طرف آپ کی وحدانیت اور میری نبوت کی نشانی ہو.\nشَهِيدًاگواہ."],[128,"§الأنعام\ndeeds\nآج خاموشی سے اللہ کے لئے کوئی نیک کام کیجئے.\nپچھلی امتوں کی ہلاکت کے تین اسباب کی نشاندہی کیجئے.\nآپ پر کوئی مصیبت آئی ہواور آپ نے اللہ کی نافرمانی کا کوئی کام کیا ہو توان دونوں کے درمیان تعلق جوڑنے کی کوشش کیجئے.\nguid\nزیادہ سے زیادہ اللہ سبحانہ وتعالیٰ کی حمدوثنا کرتے رہئے ،کیونکہ اللہ کی تعریف اور اس کی شکرگزاری ان اہم عبادات میں سے ہیں جو آپ کو اللہ سے قریب کرتی ہیں.\nدین کا مذاق اڑاناعذابِ الٰہی کا سبب اور اس کے جلد آواقع ہونے کا باعث ہے.\nجو بھی مصیبت آتی ہے تو یقیناًاس کی وجہ کوئی گناہ ہی ہوتا ہے اور توبہ کے ذریعہ ہی اس سے نجات ملتی ہے.\nrefl\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ١\nعلماء کہتے ہیں: مشرکین کے خلاف اور ان کے علاوہ اہلِ بدعت نیز دوبارہ زندہ کئے جانے اور اٹھائے جانے کو جھٹلانے والوں کے خلاف۔سورۂ اَنعام حجت ودلیل پیش کرنے اور ان کی تردید کرنے میں اصل اور بنیاد ہے ۔چنانچہ اس چیز کا تقاضا تھا کہ یہ پوری سورت یکبارگی ،اکٹھانازل کی جائے کیونکہ یہ دلیل وحجت کی حیثیت سے ایک ہی معنی ومضمون رکھتی ہے۔ (القرطبی: ۸؍۳۱۲)\nسورۂ اَنعام پوری کی پوری ایک ہی بار میں کیوں نازل ہوئی؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ١\nاللہ فرماتا ہے: اے لوگو! حمدو شکر کو خالص اسی کے لئے کروجو تمہارا اور آسمانوں اور زمین سب کا خالق ہے اور اس معاملے میں اس کے ساتھ کسی کو بھی یا کچھ بھی شریک نہ بناؤکیونکہ تمہارے ساتھ اللہ کے احسانات اور تم پر اس کے انعامات کی بدولت صرف وہی ہے جو حمدوتعریف کا مستحق ہے ،اس کے علاوہ کوئی بھی اس کا مستحق نہیں ،نہ وہ جن کی تم اللہ کے سوا عبادت کرتے ہواور نہ اللہ کی مخلوقات میں سے کوئی اور ہستی جنہیں تم اللہ کا شریک ٹھہراتے ہو۔ (الطبری: ۱۱؍۲۴۷)\nحمدوتعریف کو صرف اللہ کے لئے خالص کرنا ہم پر کیوں فرض ہے؟\nوَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ\nاللہ تعالیٰ نے (ٱلظُّلُمَٰتِ) یعنی اندھیروں کو جمع کے لفظ سے ذکر کیا ہے اس لئے کہ اندھیروں یعنی گمراہیوں کے وسائل وذرائع بہت سے ہیں اور اس کے راستے طرح طرح کے اور الگ الگ قسموں کے ہیں۔جبکہ اندھیروں کے مقابلہ میں اجالے کو واحد ذکر فرمایا ہے ۔اس لیے کہ اللہ تک پہنچانے والا راستہ یعنی صراطِ مستقیم ایک ہی ہے ۔اس میں تعدّد نہیں اور یہ وہ راستہ ہے جوحق کو جاننے اور اس پر عمل کرنے پر مشتمل ہے۔ (السعدی:۲۵۰)\n(ٱلظُّلُمَٰتِ) (اندھیرے)کو جمع کے لفظ کے ساتھ اور (ٱلنُّورَۖ)(روشنی ) کو واحد لانے کی کیا وجہ ہے؟\nهُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ ٢\nاللہ تعالیٰ نے دنیا اور زندگی کے خاتمہ کی مدت کے لئے (مُسَمًّى عِنْدَهٗ) یعنی اس کے پاس مقرر اور متعین کی صفت استعمال فرمائی ہے۔ اس لئے کہ اللہ تعالیٰ نے قیامت کا علم اپنے لئے مخصوص کرلیا ہے۔ (ابن عطیہ:۲؍ ۲۶۷)\nاَجل یعنی مدت ومیعاد کو (مُسَمًّى عِنْدَهٗ) یعنی اللہ کے پاس مقرر ہونے کے ساتھ کیوں ذکر کیا گیا ہے؟\nوَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ٤\nاعراض یعنی منہ موڑنااور روگردانی کرنا یہ ہے کہ :آسمانوں،زمین اور ان کے بیچ کی چیزوں کو پیدا کرنے،ان کی بناوٹ اور اسی قسم کی دوسری نشانیوں میں غور وفکر کرنا چھوڑدیا جائے ،جن سے اللہ عزوجل کی توحید پر دلیل پکڑناواجب ہے۔(البغوی: ۲؍ ۱۰۰)\nاللہ کی نشانیوں سے اعراض کیسے ہوتا ہے؟\nأَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ٦\nاے لوگو!تم اس بات سے ڈرتے رہوکہ ہلاکت زدہ لوگوں کی طرح تم پر بھی ہلاکت آپہنچے کیونکہ تم ان کے مقابلے میں اللہ کے نزدیک زیادہ عزت وقوت والے نہیں ہو جبکہ وہ رسول جنہیں تم نے جھٹلادیا ہے ‘اُن کے رسول کے مقابلے میں اللہ کے پاس زیادہ شرف ومرتبے والے ہیں ۔لہٰذا اگر اللہ کا لطف وکرم اور احسان نہ ہو توتم ان کے مقابلے میں عذاب او ر جلد سزادئیے جانے کے زیادہ حقدار ہو۔ (ابن کثیر: ۲؍ ۱۱۷)\nان بستیوں اور شہروں کے بارے میں اللہ کی سنت کیا ہے جن کا شر خیر سے بڑھ جائے؟\nفَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ٦\nرب کے اس ارشاد کا مطلب ہے کہ:ہم نے انہیں خوب فراوانی کے ساتھ نعمتیں عطافرمائیں مگر انہوں نے نعمتوں کی ناقدری کی ۔(فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ)پس ہم نے ان کے گناہوں کی وجہ سے انہیں ہلاک کردیا۔معلوم ہوا کہ گناہ ، اللہ کی سزا اور انتقام کا اور نعمتوں کے چھِن جانے کا سبب ہیں۔ (وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ) اور ان کے بعد ہم نے دوسری قومیں پیدا کردیں۔لہذا ان لوگوں کو بھی ہلاکت اور برے انجام سے ڈرتے رہنا چاہئے۔ (القرطبی: ۸؍۳۲۶)\nاللہ تعالیٰ کا عذاب آنے کا کیا سبب ہے؟\nwords\nوَجَعَلَجو بھی مصیبت آتی ہے تو یقیناًاس کی وجہ کوئی گناہ ہی ہوتا ہے اور توبہ کے ذریعہ ہی اس سے نجات ملتی ہے.\nيَعدِلُونَوہ دوسروں کے اس کے برابر کرتے ہیں ۔ شریک ٹھہراتے ہیں.\nتَمتَرُونَتم شکوک و شبہات کااظہار کرتے ہو.\nوَهُوَ اللَّهُوہ معبود برحق.\nقَرنٍلوگوں کا ایک گروہ.\nمِدرَارًاموسلا دھار.\nلاَ يُنظَرُونَوہ مہلت نہیں دیے جائیں گے."],[129,"§الأنعام\ndeeds\nایک پیغام بھیج کر بندوں اور خاص طور سے نیک بندوں کا مذاق اڑانے کی سنگینی واضح کیجئے.\nیاد کیجئے کہ اللہ نے اپنے اوپر رحمت کو واجب کرلیا ہے ،پھر اس سے خوب گڑگڑا کردعا مانگئے کہ وہ آپ پر رحم کرے اور آپ کو بھی مخلوق پر رحم کرنے والا بنائے.\nاگر آپ کا نفس آپ کو کبھی گناہ کی طرف راغب کرے تو اللہ تعالیٰ کا یہ فرمان دہرائیے\nguid\nاللہ تعالیٰ کے علاوہ کسی کو بھی اپنامعبود نہ بنائیے کہ آپ اس کی عبادت کرنے لگیں اوراللہ کو چھوڑ کر اس پر بھروسہ کربیٹھیں.\nاگر کوئی آپ کا مذاق اڑائے تو یاد کیجئے کہ آپ سے پہلے رسولوں کا بھی مذاق اڑایا گیا ،چنانچہ غم نہ کیجئے اس لئے کہ آخرکار بہترین انجام تقویٰ کا ہی ہے.\nاللہ کے احکام کی تعمیل میں جلدی کیجئے.\nrefl\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ١١\nاگر اس (پچھلی آیت میں بیان کردہ حقیقت) کے بارے میں تمہیں کوئی شک اور شبہ محسوس ہوتا ہے تو زمین میں چلو پھرواور جھٹلانے والوں کا انجام دیکھو ۔ تو تم پاؤگے کہ ایسی قوم ہلاکت ہی سے دوچار ہوئی ہے۔اور یہ چلنا پھرنا جس کا حکم دیا گیا ہے اس سے دراصل دلوں اور جسموں، دونوں کا ایسا چلنا پھرنا مراد ہے جس سے عبرت ونصیحت حاصل ہوورنہ عبرت ونصیحت حاصل کئے بغیر صرف دیکھنا ہی دیکھنا ہو تو اس طرح چلنے پھرنے میں کچھ بھی فائدہ نہیں ہے۔ (السعدی:۲۵۱)\nہلاک کی گئی قوموں کے آثار ونشانات دیکھنے میں مسلم اور غیر مسلم کے درمیان کیا فرق ہے؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ١٢\nجن لوگوں نے اللہ کی طرف سے پیٹھ پھیر لی ہے ۔یہ آیت اللہ کی جانب سے ان سے ہمدردی کا اظہار کرتی اور انہیں اللہ کی جانب متوجہ ہوجانے کی رغبت دلاتی ہے اور یہ خبر دیتی ہے کہ اللہ بندوں پر بڑاہی مہربان ہے ،سزادینے میں جلدی نہیں کرتااوربندے کی اِنابت وتوبہ قبول فرماتا ہے۔ (البغوی: ۲؍۱۰)\nوہ مقصود بیان کیجئے جو آیت سے اللہ کی مراد ہے؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ\nاللہ تعالیٰ نے بندوں پر اپنی رحمت واحسان کی ٹھنڈی چھاؤں پھیلادی ہے ،انہیں اپنی مہربانی اور کرم فرمائی کے دامنِ لطف میں ڈھانپ رکھا ہے اور اپنی ذات کے لئے یہ بات لکھ کر طے کرلی ہے کہ اس کی رحمت اس کے غصہ پر غالب ہے ۔نیز اس کے نزدیک عطاکرنا محروم کرنے سے زیادہ محبوب ہے اور یقینی طور پر اللہ نے بلا تفریق تمام بندوں کے لئے اپنی رحمت کے دروازے کھول رکھے ہیں ۔اگر وہ خود اپنے گناہوں کے ذریعہ اپنے لئے ان دروازوں کو بند نہ کرلیں اور اللہ تعالیٰ بندوں کو اپنی رحمت کے کھلے دروازوں کی طرف بلاتا ہے اگر خود ان کی نافرمانیاں اور برائیاں اس کی تلاش و جستجو میں رکاوٹ نہ بن جائیں۔ (السعدی: ۲۵۱)\nکون سی چیز ہے جو بندے کو اپنے رب سبحانہ وتعالیٰ کی رحمت سے فائدہ اٹھانے سے محروم کردیتی ہے؟\nقُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ\nیہاں یہ خبر دینا کہ آسمانوں اور زمین میں جو کچھ ہے سب کا مالک ومختار اللہ تعالیٰ ہی ہے۔ ایک سوال پیدا کرتا ہے، وہ یہ کہ جب سب کچھ اسی کا ہے تو جو لوگ خود اس کی ملکیت کی بعض چیزوں اور بعض مخلوق کو اس کے ساتھ شریک کرتے ہیں تواللہ تعالیٰ انہیں عذاب دینے میں جلدی کیوں نہیں کرتا ؟ چنانچہ کافر شخص اعتراض کرتے ہوئے کہتا ہے: اگرتمہاری بات۔کہ سب کچھ اللہ کا ہی ہے اور ہم کفروشرک کررہے ہیں ۔سچ ہوتی تو اللہ ہمیں فوری عذاب دیتاجبکہ مومن بندہ یہ خیال کرسکتا ہے کہ ان دشمنان حق کو سزا دینے میں بڑی دیر ہورہی ہے ۔ایساکیوں؟چنانچہ اللہ تعالیٰ کا یہ فرمان:(كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ ) اللہ نے اپنے آپ پر رحمت کو لازم کرلیا ہے۔یہ کافر اور مومن دونوں کا جواب ہے کہ مجرمین کو جلد عذاب نہ دینا ، دراصل اللہ کی رحمت ومہربانی ہے۔ لہذا اس میں ایک تو کامل رحمت ہے :یہ اللہ کے نیک بندوں کے ساتھ کی جانے والی مسلسل رحمت ہے۔اور ایک عارضی اور وقتی رحمت ہے جو گنہگاروں اور گمراہ لوگوں کے لئے مہلت اور ڈھیل دینے کی رحمت ہے۔ (ابن عاشور: ۷؍۱۵۱)\n(كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ )اللہ نے اپنے اوپر رحمت کو لازم فرمالیا ہے۔کی اپنے ماقبل جملہ سے کیامناسبت ہے؟\nوَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١٣\nیہاں‘‘سکون’’ کو خاص طور پر ذکر کیا گیا ہے اس لئے کہ ساکت و پرسکون مخلوقات میں اللہ کی نعمتیں زیادہ ہوتی ہیں ۔ (البغوی: ۲؍ ۱۱)\nاللہ تعالیٰ نے مذکورہ آیت میں‘‘ سکون’’ کو بطور خاص کیوں ذکر فرمایا ہے؟\nقُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ١٤\nآیت میں لفظ (أَوَّلَ) کو اسلام میں زیادہ مضبوط ہونے، جما ہوااورپائیدار ہونے کے معنی میں لینا درست ہے کیونکہ ہر عمل میں (أَوَّلَ) وہی ہوتا ہے جو اس کام کی سب سے زیادہ خواہش و رغبت رکھتا ہواور اس کا دل اس سے اٹکاہوا ہو لہٰذا اول ہونے کا لازمی تقاضا ہے کہ آدمی کے اندر شوق ورغبت ہو اور عمل میں پختہ اورمضبوط ہو جیسے اللہ تعالیٰ نے موسیٰ علیہ السلام کا قول نقل فرمایا ہے کہ : (وَ اَنَا اَوَّلُ الْمُؤْمِنِيْنَ) (سورۂ اعراف: ۱۴۳) یعنی میں مومنوں میں سب سے پہلے ایمان لانے والا ہوں۔کیونکہ موسیٰ علیہ السلام کا پہلا مومن ہونا تو معلوم بات تھی ۔پھر یہاں (أَوَّلَ) سے ان کی مراد یہ تھی کہ اب اللہ کی تجلّی سے بے ہوش ہوجانے کے بعد میں ایمان میں تمام لوگوں سے زیادہ مضبوط ہوگیا ہوں۔ (ابن عاشور: ۷؍۱۵۸)\nیہاں آیت میں ‘‘اولیت ’’سے کیا مراد ہے اور اس سے آپ کو کیا فائدہ حاصل ہورہا ہے؟\nوَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ١٧\nیہاں اللہ تعالیٰ نے اپنے فرمان:(وَإِن يَمۡسَسۡكَ بِخَيۡر)اگر اللہ تمہیں کوئی بھلائی پہنچائے۔کے فوراًبعد(فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ)تو وہ ہر چیز پر قدرت رکھنے والا ہے۔کہہ کر اس بات کی جانب اشارہ فرمایا ہے کہ اللہ تعالیٰ جس کسی بندے کو اپنے فضل وکرم سے نوازنا چاہے تو کسی کی طاقت ومجال نہیں کہ اللہ کے ارادے کے برخلاف ان نوازشات کو اس سے روک سکے جیسا کہ اللہ تعالیٰ نے خود اس بات کی صراحت اپنے اس قول میں کردی ہے : (وَ اِنْ يُّرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهٖ) (سورۂ یونس: ۱۰۷) اور اگر وہ تمہیں کوئی خیر وبھلائی پہنچانا چاہے تو اس کے فضل کو کوئی ٹالنے والا نہیں۔ (الشنقیطی: ۱؍ ۴۷۵)\nاس آیت کو (فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ) کے فرمان کے ساتھ ختم کرنے کی کیا مناسبت ہے؟\nwords\nوَلَلَبَسنَاہم ان کو ملا دیں گے یہاں تک کہ معاملہ ان پر مشتبہ ہو جائ.\nفَحَاقَاور نازل ہوا.\nيَمسَسكَپہنچے آپ کو."],[130,"§الأنعام\ndeeds\nآج خوب کثرت سے یہ دعا پڑھئے: (رَبِّ زِدْنِيْ عِلْمًا) میرے رب! میرے علم میں اضافہ فرما.\nکوئی ایک شرعی مسئلہ یاد کیجئے جسے آپ سمجھ نہ سکے ہوں،پھر بکثرت استغفار کیجئے ممکن ہے کہ اسے سمجھنے کی توفیق مل جائے.\nکسی قبرستان کی زیارت کیجئے یا کسی قبر کا تصور کیجئےپھر اس آیت کو ذہن میں لائیے.\nguid\nاپنی ذات و جان سے جھوٹ بول کر دھوکہ دینا اور اسے گناہوں پر راضی کرلینا اور نیکیوں میں سستی کرنا قیامت کے دن کچھ کام نہ آئیگا کیونکہ اس دن ساری حقیقتیں کھل کر سامنے آجائیں گی.\nغلط عقائد وافکار قیامت کے دن آدمی کے ذہن ودماغ سے غائب ہوجائیں گے.\nقرآن میں غور وفکر کی راہ میں گناہ رکاوٹ بن جاتے ہیں.\nrefl\nقُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ\nاللہ تعالیٰ اپنے اقرار وتصدیق اور فعل کے ذریعہ میرے حق میں گواہی دیتا ہے ،میں تم لوگوں سے جو بھی کہتا ہوں وہ مجھے اس پر برقرار رکھتا ہے... پس چونکہ اللہ تعالیٰ حکمت والا،قدرت والا ہے لہذا اس کی حکمت اور قدرت کو یہ بات زیبا اور لائق نہیں ہے کہ وہ ایسے شخص کو برقرار رکھے جو یہ دعویٰ کرتا ہو کہ اللہ نے اسے رسول بناکر بھیجا ہے حالانکہ اللہ نے اسے نہیں بھیجا۔اور اللہ نے اسے لوگوں کو اپنی طرف دعوت دینے کا حکم دیا ہے جبکہ حقیقت میں اللہ نے اسے ایسا حکم نہیں دیا ۔نیز یہ دعویٰ بھی کرتا ہو کہ جو بھی اس کی مخالفت کریگا اللہ نے اس کے لئے ایسے مخالفین کی جانوں کو، مال ودولت کو اور عورتوں کو حلال کردیا ہے۔ایسے جھوٹے دعووں کے باوجود اللہ تعالیٰ اپنی منظوری اور فعل کے ساتھ اس کی تصدیق کرے ،نیز کھلے ہوئے معجزات اور واضح آیات کے ذریعہ اس کی تائید کرے!اور مدد کرےاور جو اس کا مخالف ہودشمن ہواللہ تعالیٰ اسے ذلیل و رسوا کرے لہٰذا اللہ کی اس گواہی سے بڑھ کر کون سی گواہی ہوگی! (السعدی: ۲۵۲۔۲۵۳)\nرسول اللہ صلی اللہ علیہ وسلم اور آپ کو جھٹلانے والوں کے درمیان اللہ کے گواہ ہونے کی کیا صورت ہے؟\nوَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ\nاللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو پہلے ان لوگوں تک پیغام حق پہنچانے کا حکم دیا جو جگہ ومقام اور رشتہ وتعلق کے اعتبار سے آپ کے قریب تر اور قریب ہوں۔ پھر یکے بعد دیگرے مختلف جماعتوں اور گروہوں تک تبلیغ کریں،یہاں تک کہ حق کو جھٹلانے والوں کو برے انجام سےڈرانے کا یہ عمل دنیا کے تمام لوگوں تک پہنچ جائے جیسا کہ اللہ تعالیٰ نے فرمایاہے: (وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ ) میری طرف یہ قرآن وحی کیا گیا ہے تاکہ اس کے ذریعہ میں تمہیں بھی ڈراؤں اور ان سب کو بھی ڈراؤں جن تک یہ پہنچے۔یعنی ہر وہ شخص اور گروہ جس تک قرآن پہنچے لہذا دنیا کا ہر وہ انسان جس تک قرآن پہنچ گیا تو محمد صلی اللہ علیہ وسلم نے اسے ڈرادیا ،آگاہ کردیا۔ (ابن تیمیہ:۳؍۲۰)\nدینِ اسلام کی تبلیغ شرعی فریضہ ہے ۔اس فرض کو ادا کرنے کے کیامراحل اور طریقے ہوں گے؟\nوَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ\nتم اور تمہارے علاوہ دنیا کے تمام لوگوں میں سے جس کسی انسان تک قرآن پہنچ جائے ،اگر وہ قرآن کی تعلیمات کو نہیں اپناتا ،اس کی حلال کی ہوئی چیزوں کو حلال اور حرام کی ہوئی چیزوں کو حرام نہیں سمجھتا اور اس میں موجود تمام باتوں پر ایمان نہیں لاتاتو میں ایسے ہر شخص کوصاف صاف ڈرارہا ہوں کہ اس کی ان حرکتوں کے بدلے میں اللہ کا عذاب نازل ہوگا اور اسے اپنی کرتوت کا خمیازہ بھگتنا پڑیگا۔ (الطبری: ۱۱؍ ۲۹۰)\nقرآن کو نازل کرنے کا سب سے اہم اوربڑا مقصدہے ‘‘اس پر عمل کرنا’’ اس بات کی وضاحت کیجئے.\nٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ٢٤\n(وَضَلَّ عَنۡهُم) ان سےدور ہوگئے، غائب ہوگئے۔ (مَّا كَانُواْ يَفۡتَرُون) جو کچھ وہ بتوں کے بارے میں جھوٹ تراشا کرتے تھے ۔ دراصل وہ لوگ اپنے ان بتوں سے یہ امید رکھتے تھے کہ وہ ان کی سفارش اور مدد کریں گے لیکن قیامت کےدن اُن کی ایسی تمام امیدوں پر پانی پھر جائیگا اور ان کی یہ امیدیں باطل ثابت ہوں گی۔ (البغوی: ۲؍ ۱۴)\nقیامت کے دن کفار ومشرکین کا جھوٹ اور باطل کس طرح گم ہوگا؟\nوَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ\nیعنی: ان مشرکین میں کچھ لوگ ایسے بھی ہیں جنہیں بعض اوقات ،کچھ اسباب وعوامل آپ کی باتیں سننے پر آمادہ کرتے ہیں چنانچہ وہ آپ کی بات بظاہر تو سنتے ہیں لیکن یہ سننا، حق کو جاننے اور ماننے اور اس کی اتباع کرنےکے جذبے سے خالی ہوتا ہے ۔ اسی لئے انہیں آپ کی باتیں سننے سے کوئی فائدہ حاصل نہیں ہوتا کیونکہ ان کے ارادے اور نیت میں خیروحق کا حصول نہیں ہوتا۔ (وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً) یعنی : ہم نے ان کے دلوں پر پردے اوررکاوٹ ڈال دیے ہیں تاکہ وہ اللہ کے کلام کو نہ سمجھ سکیں۔اس طرح اللہ نے ایسے لوگوں سے اپنے کلام کو محفوظ کردیا۔ (السعدی: ۲۵۴).\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ\n(وَ جَعَلْنَا عَلٰى قُلُوْبِهِمْ اَكِنَّةً اَنْ يَّفْقَهُوْهُ) اور ہم نے ان کے دلوں پر پردے ڈال رکھے ہیں کہ وہ سمجھ ہی نہ سکیں۔ لفظ (اَكِنَّةً) کنان کی جمع ہے جس کا معنی ہے پردہ۔ اور(أَن يَفۡقَهُوهُ) کاجملہ‘‘مفعول لأجلِہ’’واقع ہے (یعنی وہ مفعول جو فعل کی وجہ بتاتا ہے ) اور اس کی مخفی تعبیر اس طرح ہے: “كراهة اَنْ يَّفْقَهُوْهُ” جس کامطلب ہے کہ اللہ نے ان کے سمجھنے کو ناپسند کرنے کی وجہ سے ان کے دلوں پر پردے ڈال دئیےاورپوری آیت کا معنی یہ ہوا کہ جب یہ لوگ قرآن کو سنتے ہیں تو اللہ تعالیٰ ان کے اور ان کی سمجھ بوجھ کے درمیان حائل ہوجاتا ہے اور اس معنی کو ادا کرنے کے لئے (اَكِنَّةً) پردہ اور (وَقۡرٗاۚ) (ڈاٹ)کے لفظ سے تعبیر کرنا،معنی میں مبالغہ اور زیادتی کے لئے ہے ۔ (ابن جزی: ۱؍ ۲۶۶)\nکافروں کا قرآن سے فائدہ نہ اٹھاپانے کا سبب بیان کیجئے؟\nوَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ٢٦\nیعنی: ان کی کارستانی کا وبال خود انہی پر آئیگا،نیزجن لوگوں کو یہ حق سے روکتے ہیں ان کے بوجھ بھی ان کے سرہوں گے۔ (وَمَا يَشۡعُرُونَ) مگر وہ سمجھتے نہیں ہیں۔ (البغوی: ۲؍ ۱۶)\nایسا بھی ہوتا ہے کہ انسان اپنے گناہ کے ساتھ دوسروں کے گناہ کا بوجھ بھی اٹھاتا ہے۔ یہ کیسے ہوتا ہے؟\nwords\nفِتنَتُهُمان کے جوابات.\nأَكِنَّةًپردے/ڈاٹ.\nوَقرًابوجھ / بہرا پن.\nأَسَاطِيرُ الأَوَّلِينَوہ حکایات جن کی کوئی حقیقت نہ ہو.\nوَيَنأَونَاور وہ بعید سمجھتے ہیں."],[131,"§الأنعام\ndeeds\nخوب نیک اعمال کیجئے اور بکثرت نوافل بھی پڑھئے تاکہ قیامت کے دن نیکیوں میں کوتاہی پر افسوس نہ کرنا پڑے.\nکوئی ایسی عبادت جسے آپ کرنا چاہتے تو ہو ں لیکن سستی یا غفلت سے اسے نہ کرپائے ہوں تو آج ہی اسے کرڈالئے.\nاپنے رشتے داروں یا جان پہچان والوں کو بھلائی کی دعوت دیجئے اور اگر ان کی جانب سے تکلیف پہنچے تو اس پر صبر کیجئے.\nguid\nقیامت کے دن سب سے برا بوجھ جو انسان اٹھائیگا وہ گناہوں کا بوجھ ہوگا.\nعقلمندوں کے لئے قرآن کی نصیحت یہی ہے کہ وہ دنیاوی زندگی سے دھوکاکھاکر آخرت کے معاملے میں لاپرواہی نہ کریں۔ اسی میں بندے کی بھلائی ہے.\nاگر لوگ داعی کو جھٹلاتے ہیں تو وہ اسے انوکھا اورنیاعمل نہ سمجھے کیونکہ یقیناًلوگ اس سے پہلے اللہ کے رسولوں کو بھی جھٹلاچکے ہیں.\nrefl\nبَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ٢٨\nبلکہ وہ یعنی کفار ومشرکین اپنے کئے ہوئے جس شرک کا انکارکررہے ہوں گے اور کہہ رہے ہوں گے (وَ اللّٰهِ رَبِّنَا مَا كُنَّا مُشْرِكِيْنَ) ‘‘اللہ ہمارے رب کی قسم! ہم شرک کرنے والے نہیں تھے’’۔ ان کے اس انکار کی قلعی کھل جائیگی،ان کا جھوٹ بے نقاب ہوجائیگا،کیونکہ اللہ ان کے اعضاء وجوارح کو گویائی عطا کریگا، وہ بولنے لگیں گے اور خود ان کے خلاف ان کے کفر وشرک کی گواہی دیں گے۔ (القرطبی: ۸؍۳۵۴)\nکفار قیامت کے دن پہلے کس چیز کو چھپانے کی کوشش کریں گے؟ اور ان کے سامنے حقیقت کیسے کھل جائیگی؟\nوَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ٣٢\nرہی دنیا کی حقیقت ! تو یہ بس تن بدن کا کھیل وتماشا ہے ،دلوں کی تفریح اور بہلاوا ہے اسی لئے لوگوں کے دل اس پر فریفتہ ہوتے ہیں،انسانی نفوس اس کے عاشق وشیدا ہوتے ہیں، خواہشات اس میں اٹکی رہتی ہیں اور ارادے اس سے الجھے رہتے ہیں۔اور دنیا کے لہو ولعب میں مشغولیت ایسی ہوتی ہے جیسے بچے کھیل کود میں مگن ہوتے ہیں۔اور رہی آخرت!تو وہ(خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ) یعنی: اپنی ذات وحقیقت اور صفات میں ،نیز باقی اور دائمی ہونے کےلحاظ سے اہل تقویٰ کے لئے کہیں بہتر ہے ۔وہاں ہرنفس کی من چاہی چیز موجود ہوگی،آنکھوں کی ٹھنڈک اور لذت کا بھرپور سامان ہوگا یعنی دل وجان کی نعمتیں اور مسرت وخوشیوں کے اسباب فراوانی سے مہیا ہوں گے لیکن لطف ولذت کے یہ انعامات ہر کسی کے نصیب میں نہیں ہوں گے۔ یہ تو صرف متقی لوگوں کے لئے ہوں گے جو اللہ کے احکامات پر عمل کرتے تھے اور اُن چیزوں سے باز رہتے تھے جن سے اللہ نے منع کیا اور روکا تھا ۔ (السعدی: ۲۵۲۔۲۵۳)\nدنیا کے سامان اور آخرت کی نعمت کے درمیان دوفرق بیان کیجئے.\nوَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ٣٢\nدنیا کی وہ چیزیں اور کام ‘لہو ولعب میں شامل نہیں ہیں جن کا تعلق آخرت کے امور سے ہے کیونکہ ’’لعِب‘‘ یعنی کھیل، حقیقت میں اس چیز کو کہا جاتا ہے جس سے فائدہ حاصل نہ ہو ۔ اور ‘‘لہو’’ یعنی وہ چیز جس میں آدمی لگا رہے اور غافل ہوجائے ۔ لہذا جن کاموں کا مقصد ومطلوب آخرت ہو وہ ان سے خارج ہیں۔ عبداللہ بن عباس رضی اللہ عنہما نے فرمایا: لہو ولعب والی زندگی دراصل کافر کی زندگی ہے اس لئے کہ وہ اپنی زندگی دھوکے اور باطل میں رہ کر گذارتاہے ۔ رہی مومن کی زندگی تو وہ نیک اعمال سے جڑی ہوتی ہے لہٰذا یہ ۔اعمال صالحہ پر مشتمل زندگی۔ لہو ولعب سے خارج ہے۔ (القرطبی: ۸؍۳۶۱)\nکیا دنیا کی ہر چیز لہو ولعب یعنی کھیل تماشا ہے؟\nفَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ٣٣\nیہاں اللہ نے ان کفار سے تکذیب یعنی جھٹلانے کی نفی کی ہے اور ‘‘جُحود’’یعنی انکارکااثبات کیا ہے ۔ اور یہ بات معلوم ہے کہ ان کا زبان سے جھٹلانا موجود تھا ۔ اس کی نفی نہیں کی گئی۔ لہذا معلوم ہوا کہ ان سے جس جھٹلانے کی نفی کی جارہی ہے وہ دل کا جھٹلانا ہے۔ (ابن تیمیہ: ۲؍ ۲۳)\nآیت کریمہ میں کس تکذیب کی نفی کی گئی ہے؟\nوَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ\n(بہت سے پیغمبر نے اپنے جھٹلانے پر صبر کیا) لہٰذا جس طرح ان رسولوں نے صبر کیا ،آپ بھی صبر کیجئے ۔نتیجہ میں آپ بھی ویسے ہی فتح وکامیابی پائیں گے جس طرح وہ فتح وکامیابی سے ہمکنار ہوئے ۔ (السعدی: ۲۵۵)\nپچھلے رسولوں کے واقعات اور ان کی سیرتوں کو بیان کرنے کی کیا مصلحت ہے؟\nوَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ ٣٤\n(وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ) اور رسولوں کی خبروں میں سے بہت سی چیزیں تو آپ تک پہنچ ہی چکی ہیں۔ اس سے مراد رسولوں کا صبر وتحمل ہے اور پھر صبر کرنے پر اللہ کی طرف سے ان تک مددکا پہنچنا ہے ۔ یہ بات بھی دراصل اللہ کے وعدے کی تاکیدہے اور صبر پر ابھارنے والی ہے ۔(ابن جزی: ۱؍ ۲۶۶)\nقرآن نازل کرنے کا سب سے بڑا مقصد ‘‘اس پر عمل کرنا’’ہے۔اس بات کی وضاحت کیجئے.\nوَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ ٣٥\n‘‘اللہ نے اپنے نبی صلی اللہ علیہ وسلم کو حکم دیا ہے کہ یہ کفار اگر ایمان نہیں لاتے توان کے بارے میں بہت زیادہ رنج وغم میں نہ پڑیں کیونکہ آپ ان کی ہدایت پر قدرت نہیں رکھتے ’’۔(القرطبی: ۸؍۳۶۷)\nجن کو دعوت دی جارہی ہے اگر وہ دعوت قبول کرنے سے روگردانی کررہے ہیں تو دعوت دینے والے کو اس پر غمزدہ ہونے سے منع کیا گیا ہے۔ اس کی کیا حکمت ومصلحت ہے؟\nwords\nكَبُرَبہت گراں."],[132,"§الأنعام\ndeeds\nجانوروں یا پرندوں کی کسی قسم کی تعیین کیجئے اور اس پر خوب اچھی طرح غور وفکرکیجئے کہ وہ کس طرح انسانوں اور دیگر امتوں کی طرح ایک مکمل امت ہیں.\nآج آپ نے نماز میں جو آیتیں سنی ہیں ،ان پر غور کیجئے اور سوچئے کہ ان میں اللہ کی جانب سے کتنے احکام اور ممنوعات ہیں اور آپ نے ان میں سے کن کن پر عمل کیا ہے.\nآپ کوکوئی مصیبت لاحق ہوئی ہوتواس سے نجات کے لئے اللہ سے گڑگڑا کر دعائیں مانگئے.\nguid\nہدایت تو اللہ کے ہاتھ میں ہے ،چنانچہ جس کے ہاتھ میں ہے اسی سے مانگئے.\nبیماری یا مفلسی یا دنیاکی دوسری بلائیں یقیناًآپ کو اللہ کی یاددلاتی ہیں اور آپ کو اس کی طرف لے کر جاسکتی ہیں.\nدنیا کی کشادگی اگر بندے کو اللہ کی شریعت سے دور لے جارہی ہو تو بیشک یہ یا تو ہلاکت کاآغاز ہوگی یا ہلاکت کا سبب بن جائیگی.\nrefl\nإِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ\nیہاں سننے سے مراد ہے دل کاسننااور اسے قبول کرنا۔ورنہ صرف کانوں سے سننے میں تو اچھے اور برے سب شامل ہیں۔معلوم ہوا کہ اللہ کی آیات کو سن لینے سے تمام مکلّفین یعنی تمام عاقل وبالغ انسانوں پر اللہ تعالیٰ کی جانب سے حجت قائم ہوگئی۔ (السعدی: ۲۵۵)\nوعظ ونصیحت کو سننے کے معاملے میں مومن اور غافل شخص کے درمیان کیا فرق ہے؟\nوَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ\nمَوتیٰ یعنی مُردوں سے مراد کفار ہیں۔ اس لئے کہ ان کے دل مرے ہوئے ہیں چنانچہ اللہ نے انہیں مُردوں سے تشبیہ دی ہے ۔ (ابن کثیر: ۲؍ ۱۲۴)\nکافر اورمیت(مردہ) کے بیچ مشابہت کی کیا وجہ ہے؟\nمَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ ٣٨\nکائنات کی تمام چھوٹی اور بڑی چیزیں لوحِ محفوظ میں اپنی حقیقی شکل میں محفوظ ہیں ۔ اور تقدیر کے قلم نے جو کچھ لکھا ہے، کائنات کی تمام چیزیں ہوبہو اسی کے مطابق واقع ہوتی ہیں ۔مذکورہ آیت میں اس بات کی دلیل ہے کہ کتابِ اول یعنی لوح محفوظ پوری کائنات میں رونما ہونے والی ہر چیز کو شامل ہے ۔ اور یہ حقیقت اللہ کی قضا وتقدیر کے چارمراتب میں سے ایک ہے ۔تقدیر کے چار مراتب یا درجات یہ ہیں: ۱.اللہ کا علم جو تمام چیزوں کو سمیٹے ہوئے ہے۔ ۲.اللہ کا لکھنا جو تمام موجودات اور واقعات کو گھیرے ہوئے ہے۔ ۳.اللہ کی مشیئت وقدرت یعنی اللہ تعالیٰ کا وہ ارادہ اور قدرت جو ہر مخلوق کے لئے عام ہے اور ہر چیز پر نافذ وجاری ہے ۔ ۴. تخلیق: یعنی اللہ تعالیٰ کا تمام مخلوقات کو پیدا کرنایعنی ہر وجودمیں آنے والی چیز اورہر عمل کا خالق وہی ہے۔(السعدی: ۲۵۵)\nآپ کی زندگی میں جو کچھ بھی ہوتا ہے وہ تقدیر کے مقرر کردہ چار مراتب سے گذرتاہے۔وہ چار مراتب کیا ہیں؟\nوَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ٤٢ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ٤٣\nاللہ تعالیٰ نے دوگروہوں کی مذمت بیان کی ہے :ایک وہ گروہ جن پر کوئی تکلیف یا مصیبت آتی ہے تب بھی وہ اللہ کو نہیں پکارتے ، نہ اللہ کی جناب میں عاجزی کرتے اور گڑگڑاتے ہیں اور نہ ہی اس کی طرف پلٹتے اور توبہ کرتے ہیں۔ جیسا کہ اللہ کا فرمان ہے: (وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ٤٢ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ)یعنی:آپ سے پہلے گزری ہوئی امتوں کی طرف ہم رسول بھیج چکے ہیں،پھرہم نے انہیں تنگدستی اور بیماری میں گرفتار کرلیا تاکہ وہ عاجزی سے دعا کریں مگر جب ان پر ہماری سختی اور سزا آئی تو وہ کیوں نہیں گڑگڑائے ،عاجزی کیوں نہیں اختیار کی؟ ۔ اور دوسرا گروہ ان لوگوں کا ہے جو دکھ اور مصیبت کے وقت اللہ کی بارگاہ میں عاجزی اور آہ وزاری کرتے ہیں اوراس کی طرف پلٹتے ہیں مگر جب اللہ تعالیٰ ان کا دکھ دور کردیتا ہے تو وہ پھر اللہ سے منہ موڑ لیتے ہیں۔ اللہ کے یہاں تیسرے گروہ والے تعریف کے لائق ہیں جو اللہ کو پکارتے ،دعا کرتے اور اس سے توبہ کرتے رہتے ہیں ۔ خوشی کی حالت میں بھی اللہ کی عبادت اور توبہ وانابت پر جمے رہتے ہیں ۔یعنی خوشحالی اور بدحالی دونوں میں اللہ تعالیٰ کی عبادت اور اطاعت میں لگے رہتے ہیں۔(ابن تیمیہ: ۳؍ ۲۴۔۲۵)\nخوشحالی اور بدحالی کی حالتوں میں دعا کرنے والے لوگوں کی کئی قسمیں ہیں ۔انہیں بیان کیجئے.\nوَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ٤٢ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ٤٣\n(فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ) ہم نے انہیں تنگدستی اور بیماری میں مبتلا کردیا۔ یہ چیز اللہ کی جانب سے ان کے ساتھ نرمی برتنے اور ادب سکھلانے کے طور پر ہلکی سزاتھی ۔ (فَلَوۡلَآ) تو ایسا کیوں نہیں ہوا؟یہ ان کے سامنے ایک پیشکش اور ترغیب ہے ۔اس میں اس بات کی دلیل ہے کہ مصیبت وتکلیف کے وقت عاجزی سے دعا کرنابندے کے لئے فائدہ مند ہے ۔ (ابن جزی: ۱؍ ۲۷۰)\nآیت کی روشنی میں بیان کیجئے کہ سختیوں اور مصیبتوں میں تضرّع یعنی عاجزی کے ساتھ دعا کرنے کی کیا اہمیت ہے؟\nفَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ٤٤\nہم نے ان پرخوشحالی کے وہ تمام دروازے کھول دئیے جو بند تھے۔ (حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ) اس کا معنی ہے کہ جب وہ فراوانی سے ملنے والی نعمتوں اور خوشحالی پراترانے لگے،تکبر میں مبتلا ہوگئے اور اس گمان میں پڑ گئے کہ یہ نوازشات کبھی ختم نہیں ہوں گی اور یہ نعمتیں اور نوازشیں اس بات کی علامت ہیں کہ اللہ عزوجل ان سے خوش ہے۔ (أَخَذۡنَٰهُم بَغۡتَةٗ)یعنی ہم نے انہیں جڑسے اکھاڑ دیا،نیست ونابود کردیا اورانہیں اپنے عذاب میں گھیر لیا۔(بَغۡتَةٗ)اس کا معنی ہے اچانک ،دفعۃً،ناگہاں۔مطلب ہے بے خبری میں پکڑ لینا۔ (القرطبی: ۸؍۳۷۹)\nآیت کے تناظر میں بتائیے کہ اللہ تعالیٰ غفلت میں مبتلا لوگوں کے ساتھ کس طرح ڈھیل دینے کا معاملہ کرتا ہے؟\nفَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ٤٤\nحسن بصری رحمہ اللہ کہتے ہیں:اللہ تعالیٰ جس شخص پر نعمتوں کی بارش اور کشادگی کرے اور وہ یہ نہ سمجھے کہ اللہ اس کے ساتھ تدبیر یعنی ڈھیل دینے والا معاملہ کررہا ہے تو ایسا شخص ناسمجھ ہے ۔نیزاسی طرح جس پر اللہ تعالیٰ تنگی ڈال دے اور وہ یہ نہ سمجھے کہ اللہ اسے مہلت وموقع عطاکررہا ہے تویہ بھی بے عقل ہے ۔ یہ بیان کرکے حسن بصری رحمہ اللہ نے یہی آیت تلاوت کی: (فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ) (ابن کثیر: ۲؍ ۱۲۶)\nایک مسلمان اپنی مالی کشادگی اور تنگی میں کس طرح کا رویہ اپناتاہے؟\nwords\nمَا فَرَّطنَاہم نے نہیں چھوڑا.\nصُمٌّبہرے/ جو سنتے نہیں.\nوَبُكمٌگونگے/ جو کلام نہیں کرتے.\nأَرَأَيتَكُممجھے بتاؤ.\nمُبلِسُونَنا امید /ہر خیر سے منقطع."],[133,"§الأنعام\ndeeds\nغیب کے دعوے داروں ،مستقبل کی باتیں بتانے والوں اور ستاروں کی چالوں کے جاننے کا دعویٰ کرنے والوں کا پردہ فاش کیجئے اور لوگوں کوان کی حقیقت بتائیے کہ یہ لوگ غیب نہیں جانتے.\nاپنے متعلقین کوقرآنی نصیحت پر مشتمل پیغام بھیجئے.\nآج کسی غریب یا کم مرتبہ مگر نیک آدمی کے ساتھ بیٹھئے ۔اس سے آپ کے دل کو تواضع اور لوگوں کے ساتھ نرمی برتنے کا سبق ملے گا.\nguid\nجلد یا بدیر ہلاکت ہی ظالم کا انجام ہے.\nلوگوں کو نصیحت کرتے یا دعوت الی اللہ کا کام کرتے وقت خیر کی خوشخبری اور شر سے ڈرانے پر مشتمل اسلوب اختیار کیجئے.\nاگر اللہ کے رسول اور اس کے حبیب صلی اللہ علیہ وسلم غیب نہیں جانتے تھے تو یقیناً کوئی اور بدرجۂ اولیٰ نہیں جان سکتا.\nrefl\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nاللہ تعالیٰ نے اپنی قضاء وقدر کے مطابق حق کو جھٹلانے والوں کے لئے جو تباہی کافیصلہ کیا ہے اس پر ہر طرح کی تعریف اللہ کے لئے ہی ہے جو تمام کائنات کا رب ہےکیونکہ اس کے ذریعہ کئی فائدے حاصل ہوتے ہیں،جیسے :اس کی نشانیاں اور آیتیں واضح ہوجاتی ہیں ،اس کی باتیں حق ثابت ہوتی ہیں ،اللہ کی جانب سے اس کے دوستوں کی عزت افزائی ہوتی ہے جبکہ اس کے دشمنوں کو رسوائی ملتی ہے ،نیز رسولوں کی لائی ہوئی تعلیمات وشریعت کی سچائی معلوم ہوتی ہے۔ (السعدی: ۲۵۶)\nمشرکین کو عذاب دینے کے مضمون والی آیتوں کو حمد وتعریف کے ساتھ ختم کرنے کی کیا وجہ ہے؟\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nان تمام باتوں میں اس بات پر تنبیہ اور آگاہی ہے کہ ظالموں کی ہلاکت وبربادی پر اللہ تعالیٰ حمد وتعریف کا حقدار ہے اس لئے کہ ان کے ہلاک ہوجانے میں دوسرے تمام لوگوں کی بھلائی اور بہتری ہے ۔اور صلاح ودرستگی بہت ہی عظیم نعمت ہے اور نعمت کا شکر ادا کرنا واجب ہے چنانچہ آیت میں اللہ کی یہ حمد وتعریف اس کا شکرانہ ہے اس لئے کہ یہ ایک نعمت کے جواب میں ہے ۔ (ابن عاشور:۷؍۲۳۲)\nظالموں کا ہلاک وبرباد ہونا اللہ کی ایک نعمت ہے ۔اس بات کی وضاحت کیجئے.\nفَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٤٥\nظالموں کی جڑ کاٹ دینے پر اللہ تعالیٰ نے اپنی ذات کی تعریف فرمائی ہے اس لئے کہ یہ رسولوں کے حق میں اللہ کا انعام و احسان تھا۔ چنانچہ اس مقام پر (ٱلۡحَمۡدُ لِلَّهِ) کہہ کر اور اللہ کی تعریف بیان کرکے رسولوں کو اور ان کے ماننے والوں کو تعلیم دینا مقصود ہے کہ ظالموں کے شر سے اللہ کے کافی ہوجانے پر وہ اس کی حمد وتعریف بیان کریں۔ (البغوی: ۲؍ ۲۲)\nجب ہم دیکھیں کہ اللہ نے ظالموں کو ہلاک کردیا ہے اس وقت ہمارے لئے شرعی حکم کیا ہے؟\nقُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ ٤٦\n‘‘تصریف الآیات’’ یعنی باربار آیات کو بیان کرنے اور دہرانے کا مطلب ہے : مختلف طریقوں سے بیان کرنا ،الگ الگ انداز میں پیش کرنا ۔ یہ اس طرح کہ کبھی آسمانوں اور زمین کے مشاہدے کی دلیلیں بیان کی گئی ہیں،کہیں لوگوں کے جسم وجان میں موجود دلیلوں کی حجت پیش کی گئی ہے اور کسی جگہ پچھلے زمانوں میں اللہ کی پیدا کردہ قوموں کے حالات بطوردلیل پیش کئے گئے ہیں۔ (ابن عاشور: ۷؍۲۳۵)\nآیت میں مذکور ‘‘تصریف الآیات’’ کس طرح ہوتا ہے؟\nوَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ\nیہ قرآن ساری مخلوق کے لئے ڈرانے والا اور تنبیہ کرنے والا ہے لیکن اس سے صرف وہی لوگ فائدہ اٹھاتے ہیں (ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ ) جو اس بات سے ڈرتے ہیں کہ انہیں اپنے رب کے حضور اکٹھا کیا جائیگا۔ یعنی وہ پکا یقین رکھتے ہیں کہ انہیں دنیا کے اس عارضی گھر سے آخرت کے دائمی گھر کی طرف منتقل ہونا ہی ہے ۔ نتیجہ میں وہی چیزیں اختیار کرتے ہیں جو انہیں فائدہ پہنچاتی ہوں اور نقصان دینے والی چیزوں کو چھوڑدیتے ہیں۔(السعدی: ۲۵۷)\nڈرانے کو صرف ان لوگوں کے ساتھ خاص کیوں کیا گیا ہے جو حشر یعنی قیامت کے دن اکٹھا کئے جانے سے ڈرتے ہیں؟\nوَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ\nدعاء ومناجات کے لئے صبح اورشام کے وقت کو خاص طورپرذکرفرمایاہے اس لئے کہ ان اوقات میں عام طور پر لوگ اپنے کاموں میں بہت زیادہ مشغول ہوتے ہیں ،چنانچہ جو شخص کام کی مشغولیت کے وقت میں عبادت کی طرف متوجہ ہوتا ہو وہ فرصت وفراغت کے وقت میں مصروفیت کے مقابل زیادہ عمل کرنے والا ہوگا۔ (القرطبی: ۸؍۳۸۹)\nاللہ سبحانہ نے صبح اور شام کے وقت کو خاص طور پر کیوں ذکر فرمایاہے؟\nوَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ ٥٢\nیہ آیت بلال،عمار بن یاسر،عبداللہ بن مسعود،خبّاب اور صُہیب رضی اللہ عنہم جیسے کمزور مومنین کے بارے میں نازل ہوئی۔ واقعہ یہ ہوا کہ : قریش کے بعض مشرکین نے نبی صلی اللہ علیہ وسلم سے کہا کہ: ہم اپنے الگ شرف و مقام کی بنا پر ان کمتر لوگوں کے ساتھ میل جول نہیں رکھ سکتے۔اب اگر آپ ان لوگوں کو اپنے پاس سے ہٹادیں تو ہم آپ کی اتباع کے لئے تیار ہیں۔ (ابن جُزی: ۱؍ ۲۷۱)\nیہ آیت مدعو افراد کے ساتھ سلوک و تعامل کے دعوتی و منہج وطریقہ کار کی نشاندہی کرتی ہے ۔ اسے بیان کیجئے.\nwords\nفَقُطِعَجڑیں کاٹ دیں.\nدَابِرُان کا آخر.\nنُصَرِّفُہم مختلف طرح سے پھیرتے ہیں.\nيَصدِفُونَوہ اعراض کرتے ہیں.\nبِالغَدَاةِشروع دن/ صبح سویرے."],[134,"§الأنعام\ndeeds\nاللہ نے آپ کو جو نعمتیں دی ہیں ،ان پر اس کا شکر ادا کیجئے ۔ بیشک شکر ہدایت اور رزق کی کنجی ہے.\nکسی شخص کو (اسلام کی) دعوت دیجئے اور اس کام میں اللہ تعالیٰ کی رحمت سے امید دلانے کا اسلوب اپنائیے.\nنادانی میں آپ سے کوئی گناہ ہوگیا ہو تو اسے یاد کیجئے اور اللہ سے مغفرت مانگئے.\nguid\nجب آپ جان گئے ہیں کہ اللہ نے رحمت کو اپنے اوپر لازم کر لیا ہے تو عاجزی کے ساتھ گڑگڑا کر اس سے اس کی رحمت مانگئے.\nلوگوں کے طور طریق اوران کے مذہب کے تعلق سے فیصلہ قرآن ہی کا معتبر ہے ۔چنانچہ اس کی مدد سے صحیح اور غلط منہج وطریقہ کو واضح کیاجائے گا.\nداعی کاگمراہوں اور خواہش پرستوں کی جانب سے دی جانے والی تکالیف کو برداشت کرنا اور ان پر صبر کرناایسی عبادت ہے جس کے ذریعہ اللہ کا تقرب حاصل ہوتا ہے.\nrefl\nوَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ ٥٣\n(وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ) اور اسی طرح ہم نے بعض انسانوں کو دوسرے انسانوں کے ساتھ آزمایا ہے۔ یعنی: ہم نے کافروں کو مومنوں کے ذریعہ آزمایا۔اس کی ایک شکل یہ ہے کہ :کفار کہتے تھے :کیا اللہ نے ہمیں چھوڑکر ان غلاموں اور محتاجوں کو حق اور سعادت کی توفیق بخشی ہے اوران پر احسان کیا ہے ؟جبکہ ہم قوم کے شریف ،عزت دار اور مالدار لوگ ہیں ۔ان کے اس کلام کا مطلب یہ تھا کہ ایسا ہوناممکن نہیں۔(أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ) کیا اللہ تعالیٰ اپنے شکرگزاربندوں کو ان سے زیادہ نہیں جانتا ! اس فرمان میں کافروں کی پچھلی بات کی تردید ہے۔ (ابن جزی: ۱؍ ۲۷۱)\nکمزور اور ناتواں لوگوں کی ہدایت کس طرح گمراہ لوگوں کے لئے آزمائش اور امتحان ہوتی ہے؟\nأَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ ٥٣\nشاکرین سے مراد وہ لوگ ہیں جو نعمتِ ایمان کی قدر وقیمت پہچانتے ہیں اور اس نعمت پر اللہ کا شکر بجالاتے ہیں۔ (ابن تیمیہ: ۳؍ ۲۸)\nآیت کریمہ میں شاکرین سے کون لوگ مراد ہیں؟\nوَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ ٥٤\nاور جب ایمان والے آپ کے پاس آئیں تو انہیں سلام کیجئے ،مرحبا اور خوش آمدید کہئے اور انہیں اللہ کی رحمت،اس کی بے پناہ فیاضی اوران گنت احسانات کی بشارت دیجئے جس سے ان کے حوصلے اورعزائم بلند ہوں ۔نیز انہیں اللہ کی رحمت وانعام تک پہنچانے والے ہر ذریعہ اور ہر راستے کو اختیار کرنے کی ترغیب دیجئے ۔ساتھ ہی انہیں گناہوں پر قائم وبرقرار رہنے سے ڈرائیے اور پچھلی غلطیوں اور نافرمانیوں سے توبہ کرنے کا حکم دیجئے تاکہ وہ اپنے رب کی بخشش ومغفرت اور جود وکرم پاسکیں۔ (السعدی: ۲۵۸)\nعلماء ودعاۃ کا اپنے نیک پیروکار وں کے ساتھ کس طرح کا تعلق ہونا چاہئے ؟\nوَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ٥٥\nاور جب مجرمین کا راستہ نمایاں ہوگیا تو پھر مومنوں کا راستہ بھی از خود بالکل نمایاں ہوگیا۔ (القرطبی: ۸؍۳۹۶)\nصرف مجرموں کا راستہ کیوں بیان کیا گیا ہے ،مومنوں کا نہیں؟\nوَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ ٥٥\n(تاکہ مجرمین) کا طریقہ ظاہر ہوجائےاس لئے کہ جب مجرموں کا راستہ نمایاں اور واضح ہوجاتا ہے تو اس سے بچنا اور دور رہنا ممکن اور آسان ہوجاتا ہے لیکن اس کے برخلاف اگر جرم کا راستہ مشتبہ اور غیرواضح ہو تو اس سے بچنے کا یہ اہم اور بڑا مقصد حاصل نہیں ہوپائیگا۔ (السعدی: ۲۵۸)\nمجرموں کے راستوں کو واضح طور سے بیان کرنے کی کیا حکمت ہے؟\nقُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ\n(اگر میرےپاس وہ چیز ہوتی جس چیز کی تم جلد بازی کررہے ہو) تو میں تم پر وہ عذاب واقع اور مسلط کردیتا جس کی تم جلدی مچارہے ہو اور ایسے میں تمہارے لئے کوئی بھلائی نہیں ہوتی ،لیکن معاملہ کا پورا اختیار اس ذات کے ہاتھ میں ہے جو ‘‘حلیم،صبور’’ہے یعنی بے انتہا بردبار اور بے اندازہ صبر وتحمل والا ہے کہ نافرمان لوگ اس کی نافرمانی کرتے ہیں اور سینہ زوری کرنے والے لوگ اس کے خلاف سینہ زوری کرتے ہیں ،اس کے باوجود وہ ربِّ حلیم انہیں اپنی عافیت اور معافی کے دامن میں پناہ دے دیتا ہے ،ان پر اپنے رزق کا فیضان جاری رکھتا ہے ،اتنا ہی نہیں بلکہ ان پر اپنی کھلی اور چھپی نعمتوں کے ذریعہ احسان کرتے رہتا ہے۔ (السعدی: ۲۵۹)\nیہ آیت کس طرح بتاتی ہے کہ اللہ کی رحمت بہت وسیع ہے؟\nوَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا\n(وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا ) اور کوئی پتہ تک نہیں گرتا جسے وہ جانتا نہ ہو۔ یعنی: درخت کا کوئی بھی پتہ ہو، اللہ ہر ایک کے بارے میں پوری طرح علم رکھتا ہے کہ وہ کب شاخ سے ٹوٹ کر گرے گا،کہاں گرے گااورکتنی بار ہوا میں گھومے گا؟ اسی طرح کوئی بھی دانہ یا بیج ہو اللہ تعالیٰ کو خوب معلوم ہے کہ وہ کب اُگے گا؟ کتنا اُگے گا؟ اورکون اسے کھائیگا؟ (القرطبی: ۸؍۴۰۵)\nمذکورہ آیت اللہ کے علم کے وسیع اور لامحدود ہونے کی ایک مثال بیان کرتی ہے ۔اس کی وضاحت کیجئے۔\nwords\nفَتَنَّاہم نے اختلاف رزق سے انہیں آزمایا.\nبِجَهَالَةٍحماقت سے؛ اللہ کا ہر نافرمان جاہل ہے.\nمَفَاتِحُ الغَيبِغیب کے خزانے۔ سورة لقمان میں مذکور پانچ امور."],[135,"§الأنعام\ndeeds\nانتہائی عاجزی کے ساتھ اللہ تعالیٰ سے دعا مانگئے کہ آپ کی پریشانی دور فرمادے اور آپ کی حاجت پوری کردے کیونکہ بیشک اللہ سبحانہ وتعالیٰ کے علاوہ کوئی تکالیف سے نجات دینے والا نہیں ہے.\nدوجھگڑا کرنے والے افراد یا گروہوں میں صلح کروائیے.\nپیغام بھیج کرلوگوں کو ان ذرائع ابلاغ سے خبردار کیجئے جو دینِ اسلام پر کیچڑ اچھالتے ہیں.\nguid\nاس اختلاف سے ڈرایا جارہا ہے جو تفرقہ اور جھگڑے کا سبب بنتا ہے.\nابتعد عن مجالس اللغو والباطل.\nبے فائدہ اور باطل مجلسوں سے دور رہئے.\nrefl\nوَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ ٦٢\n(اللہ کے حساب میں دیر ہونے کا سوال ہی نہیں اٹھتا)اس کی وجہ یہ ہے کہ ایک تو اللہ کا علم کامل ہے ۔دوسرااللہ نے ان کے اعمال کو محفوظ کررکھا ہے ۔ یعنی اس نے لوح محفوظ میں سب کچھ لکھ رکھا ہے ،پھر فرشتوں نے ان کے ایک ایک عمل کونامہ اعمال میں درج کررکھاہے جو ان کے ہاتھوں میں ہے۔ (السعدی: ۲۵۹)\nاللہ اپنے بندوں سے جلد حساب لینے والا ہے ۔اس بارے میں اللہ کی عظمت کیا ہے؟بیان کیجئے.\nقُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٦٣\n(لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ) تو پھر ہم ضرور اس کے شکر گذاربندے بن جائیں گے۔شکر کا مطلب ہے: نعمت کو پہچاننا اور اس کاپورا حق ادا کرنا۔ (البغوی: ۲؍ ۳۰)\nاللہ تعالیٰ کی نعمتوں کا پورا شکرکس طرح ادا ہوسکتا ہے؟\nقُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٦٣ قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ ٦٤\nاللہ تعالیٰ نے انہیں اس بات پرڈانٹا ہے کہ وہ مصیبتوں اور سختیوں میں تو صرف اسی کو پکارتے ہیں لیکن خوشحالی میں اللہ کے ساتھ دوسروں کوبھی پکارنے لگتے ہیں۔ (القرطبی: ۸؍۴۱۲)\nآیت کریمہ کے تناظر میں بیان کیجئے کہ فریاد طلب کرنے کے بارے میں مشرکین کے یہاں کیسا تضاد ہے؟\nأَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ\n(أَوۡ يَلۡبِسَكُمۡ شِيَعٗا) یا تمہیں فرقہ فرقہ بنادے۔ اس کا مطلب یہ بتایا گیا ہے کہ:اللہ تمہیں اس طرح گروہوں میں بانٹ دیگا کہ ایک گروہ دوسرے گروہ سے لڑتا بھڑتا رہے ۔ یہ اس طرح ہوگا کہ ان کے معاملے کو مشتبہ اور خلط ملط کردیگا اور دنیا کی چاہت میں ان کے اُمراء وحکام کے درمیان اختلاف وانتشار ہوگا۔ اور یہی اس فرمان کا مطلب ہے: (وَ يُذِيْقَ بَعْضَكُمْ بَاْسَ بَعْضٍ)اور تمہیں ایک دوسرے گروہ کی شدت کا مزہ چکھائیگا۔ یعنی اللہ تعالیٰ ایسی حالت کردیگا کہ فتنہ وفساد میں پڑکر تم آپس میں جنگ وجدال کروگے اور ایک دوسرے کو قتل کرکے اذیتوں کا مزہ چکھوگے۔ (القرطبی: ۸؍۴۱۴)\nمعاشرے کے مختلف طبقوں کے درمیان معاملہ خلط ملط ہوجانے سے کس طرح سزا ہوتی ہے؟\nوَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nاگر شیطان تمہارے ذہنوں سے یہ ممانعت بھلادے کہ اللہ کی آیتوں میں نکتہ چینیاں اور مخالفانہ کوششیں کرنے والوں سے الگ رہنا چاہئے ،تو جیسے ہی یہ ممانعت یاد آجائے توان کے پاس سے نکل پڑواوریاد آجانے کے بعد ان کے ساتھ نہ بیٹھو۔ (ابن جزی: ۱؍ ۲۷۴)\nاس شخص کو آپ کیا نصیحت کریں گے جو اللہ کی آیتوں میں عیب نکالنے والوں کے ساتھ رہتا اور ان کی مجلسوں میں بیٹھتا ہے اور اس کے جواز پر یہ دلیل دیتا ہے کہ ‘‘میں غور وفکر اور سمجھنے کے لئے ایسا کرتا ہوں’’؟\nوَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nجو شخص اللہ کی آیتوں میں عیب جوئی اور نکتہ چینی کرے ‘اس کے ساتھ اٹھنا بیٹھنا ترک کردیا جائیگا اور اس سے قطع تعلق کیا جائیگا چاہے وہ مومن ہو یا کافر۔ (القرطبی: ۸؍۴۱۹)\nجو شخص بدعات اور شکوک وشبہات پیش کرے۔اس کے بارے میں ہمارا کیارویہ اورطرز عمل ہونا چاہئے؟\nوَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٦٨\nخیر وبھلائی کابھول جاناشیطان کی طرف سے ہوتا ہےجیسا کہ اللہ تعالیٰ نے فرمایا: (وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ) اور اگر ایسا ہو کہ شیطان تمہیں بھلادے تو چاہئے کہ یاد آجانے کے بعد ایسے لوگوں میں نہ بیٹھو جو ظلم کرنے والے ہیں۔ (ابن تیمیہ: ۳؍ ۳۲)\nبندہ خیر وبھلائی کو کیسے بھول جاتا ہے؟\nwords\nجَرَحتُمتم نے کمایا.\nلاَ يُفَرِّطُونَوہ کوتاہی نہیں کرتے/ ضائع نہیں کرتے.\nيَلبِسَكُم شِيَعًاتمہیں باہم لڑتے گروہ بنادے.\nنُصَرِّفُہم مختلف طرح سے پھیرتے ہیں.\nيَخُوضُونَٹھٹھہ اڑاتے ہوئے کلام کرتے ہیں."],[136,"§الأنعام\ndeeds\nکوئی غیرمفید مجلس جس کے آپ عادی بن چکے ہوں اس کی تحدید کیجیئے اوراس کی جگہ کسی مفید مجلس میں وقت لگائیے.\nبعض وہ لوگ جو مُردوں کو پکارتے ہوں انہیں یہ آیت پیغام کی شکل میں لکھ کر بھیجئے.\nاس بات سے اللہ تعالیٰ کی پناہ مانگئے کہ شیطان آپ کو ورغلا کر اللہ کی راہ سے بھٹکائے اور یہ بھی دعا کرتے رہئے کہ اللہ سے ملاقات تک وہ آپ کو اپنے دین پر ثابت قدم رکھے.\nguid\nاگر کوئی امر بالمعروف اور نہی عن المنکر کا فریضہ انجام دے ،اس کے بعد گنہگاروں اور برائیوں میں مبتلا افراد سے دوری اختیار کرلے اور ان کی حرکتوں سے کنارہ کش ہوجائے تو اس پر کوئی گناہ نہیں.\nاللہ کے دین کو لطیفہ گوئی،کھیل تماشااور بے ہودہ باتوں کا نشانہ بنانے سے بہت محتاط رہئے کیونکہ اللہ کے یہاں دین کا معاملہ بہت ہی بڑا اور محترم ہے.\nقرآن اور اس کی آیات پر مشتمل بیانات دعوت الی اللہ کے مفید ترین وسائل میں سے ہیں.\nrefl\nوَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ ٦٩\nآیت میں اس بات کی دلیل ہے کہ وعظ ونصیحت کرنے والے کو ایسی گفتگو کا انتخاب کرنا چاہئے جس سے تقویٰ کا مقصد حاصل ہونے کا زیادہ امکان ہو۔ (السعدی: ۲۶۱)\nلوگوں کو وعظ ونصیحت کرتے وقت داعی کو اپنے سامنے کونسا ہدف ومقصد رکھنا ضروری ہے؟\nوَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nیعنی: اگرچہ آپ کو انہیں وعظ ونصیحت کرنے کا حکم دیا گیا ہے لیکن ان سے دل نہ لگائیے اس لئے کہ وہ ہٹ دھرم لوگ ہیں۔ اور (لَعِبٗا وَلَهۡوٗا) کھیل اور تماشا۔ سے یہ معنی مراد ہے: اس دین کی ہنسی اڑانا جس کی آپ انہیں دعوت دے رہے ہیں۔ نیز ایک قول یہ بھی ہے کہ: انہوں نے اس دین کو ہنسی مذاق بنالیاجس پر وہ خود تھے،چنانچہ انہوں نے اپنے دین پر عمل نہیں کیااور کسی بھی دین ومذہب كا ہنسی مذاق اڑانا درست نہیں ہے۔ (القرطبی: ۸؍۴۲۳)\nاللہ کے دین کو کھیل تماشا بنانا کس طرح ہوتا ہے؟\nوَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nاس جگہ (ٱلۡحَيَوٰةُ) یعنی زندگی کا تذکرہ بر موقع اور انتہائی مفید ہے ۔وہ اس طرح کہ ان لوگوں کی دنیا سے بس یہی چاہت ہے کہ اس میں زندہ رہیں ،جیتے رہیں،دنیا میں کمائی جانے والی اُن بھلائیوں ونیکیوں سے ان کو دلچسپی نہیں ہے جن کے نتیجہ میں آخرت کی سعادت حاصل ہوتی ہے ۔ مطلب یہ ہوا کہ: دنیا کی زندگی نے انہیں دھوکے میں ڈال دیا ہے اور اس وہم میں مبتلا کردیا ہے کہ دنیا کی زندگی کے بعدکوئی زندگی نہیں ہے۔ (ابن عاشور: ۷ٖ؍۲۹۶)\nآیت کریمہ میں حیات کے ذکر کرنے کا کیا فائدہ ہے؟\nوَذَكِّرۡ بِهِۦٓ\nیعنی قرآن کے ذریعہ وعظ ونصیحت کیجئے جو بندوں کے لئے فائدہ مند ہے ۔قرآن کے احکام کو بیان کرکے اور اس کی تفصیلات بتا کر ۔نیز قرآن میں جو خوبیاں اور اچھائیاں ہیں انہیں ذکر کرکے ،خوبصورت اور دلکش انداز میں اسے پیش کیجئے ۔اسی طرح جو چیزیں بندوں کے لئے نقصان دہ ہیں، ان سے منع کرتے ہوئے اور ممنوع چیزوں کی مختلف قسموں کی تفصیل بیان کرتے ہوئے قرآنی وعظ ونصیحت کرتے رہئے۔ (السعدی: ۲۶۱)\nدعوت اور لوگوں کو وعظ ونصیحت کرنے میں قرآن کے استعمال کا سب سے اچھا طریقہ کیا ہے؟\nوَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ\nیعنی: نفس اپنے گناہوں کی بدولت ان کاموں سے روک دیا جائے جن کو کرنے سے اسے دنیا اور آخرت کی نجات مل سکتی ہے ۔ اس لئے کہ آدمی کے گناہ اسے قیدی بنالیتے ہیں اسے گرفتار کرلیتے ہیں اور جکڑ کر توحید کی فضا میں چلنے پھرنے سے روک دیتے ہیں ۔اور گناہ بندے کو نیک اعمال کے اچھے نتائج وثواب سے محروم کردیتے ہیں۔اس طرح گنہگار ونافرمان شخص یہاں دنیا میں بھی محروم ہوگا اور وہاں آخرت میں بھی ۔ (السعدی: ۲۶۱)\nگناہ، گنہ گار کے لئے قید اور گرفت ہے ۔اس بات کو آیت کے تناظر میں بیان کیجئے.\nقُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ\nکچھ لوگ ایسے ہیں جو تمام معاملات میں یا اکثر معاملات میں ہدایت کی طرف بلانے والے کے ساتھ ہوتے ہیں جبکہ کچھ لوگ اس کے بالکل برعکس یعنی داعئ ضلالت کے ساتھ ہوتے ہیں مگر کچھ لوگ ایسے بھی ہوتے ہیں جن کے نزدیک ہدایت اور گمراہی دونوں کے داعی برابر اور ایک جیسے ہوتے ہیں اور دونوں اپنی اپنی جانب کھینچتے ہیں ۔ ان دومخالف کشش کے مقام پرنیک بخت اوربدبخت کی پہچان ہوتی ہے۔(السعدی: ۲۶۱۲۶۲)\nداعئ ہدایت یعنی ہدایت کی طرف بلانے والے کے سامنے لوگوں کی کتنی قسمیں ہوتی ہیں ؟اور آپ کس قسم میں ہونے کی امید رکھتے ہیں؟\nكَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ٧١\n(لَهُۥٓ أَصۡحَٰبٞ) اس کے کچھ ساتھی ہیں۔ مراد رُ فقاء واحباب ہیں جو اسے ہدایت کی طرف بلاتے ہیں یعنی : اسےہدایت کے راستے کی طرف رہنمائی کرتے ہیں اور اس سے کہتے ہیں: ہمارے پاس آجا۔لیکن وہ بھٹک گیا ہے اور ان سے دورہوگیاہے چنانچہ ان کی بات نہیں مانتا ۔یہ سب کچھ ایسے شخص کی مثال بیان کی گئی ہے جو دین کے معاملے میں ہدایت سے بھٹک جائے ،گمراہی میں پڑجائے ۔اب اسے اسلام کی طرف واپس بلایا جاتا ہے لیکن وہ اس ۔سچی اور اچھی۔دعوت کو قبول نہیں کرتا۔ (ابن جُزی: ۱؍ ۲۷۵)\nآیت کی روشنی میں بیان کیجئے کہ (حَيۡرَانَ) بھٹکا اور کھویا ہواکون ہے؟\nwords\nتُبسَلَاسے روک دیا جائے.\nتَعدِلتم اس کا فدیہ دو.\nأُبسِلُواوہ گناہوں کی پاداش میں پکڑےگئے.\nحَمِيمٍانتہائی گرم پانی.\nاستَهوَتهُاس کو پھسلایا اور گمراہ کردیا.\nالصُّورِوہ سینگ جس میں اسرائیل علیہ السلام پھونک ماریں گے."],[137,"§الأنعام\ndeeds\nبرائیوں سے روکنے کا فریضہ انجام دیجئے ۔چاہے یہ کام اپنے کسی بہت قریبی کے تعلق سے ہی کیوں نہ ہو۔ اسے حکمت کے ساتھ نصیحت کیجئے اور ایسے پیارے اسلوب میں جو اسے قبول کرنے پر آمادہ کردے.\nاللہ تعالیٰ سے دعاء مانگئے کہ آپ بھی یقین رکھنے والوں میں سے بن جائیں.\nایک پیغام بھیج کر قبرپرستوں کو نصیحت کیجئے اور انہیں اس آیت عظیمہ کے ذریعہ تذکیر کیجئے.\nguid\nاللہ تعالیٰ جسے چاہتا ہے ہدایت سے نوازتا ہے.\nیقین کے مرتبہ تک پہنچنے کی خواہش رکھئے اور جان لیجئے کہ یہ سب سے زیادہ شرف اور عزت والا مقام ہےاور اللہ کی آیات میں غوروفکر تک پہونچنے کا ذریعہ ہے.\nسب سے زیادہ خوف وگھبراہٹ کا شکار اہل شرک ہی ہوتے ہیں جبکہ اہلِ ایمان واخلاص امن وسکون میں رہتے ہیں.\nrefl\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ ٧٤\nابراہیم علیہ السلام کے اس خطاب میں ایسی کوئی بات نہیں جو باپ کے ساتھ حسنِ سلوک یا فرمانبرداری کے خلاف ہو کیونکہ کسی طرح کی بدکلامی اور زیادتی کے بغیر حق کا اظہار کرنا، حسن سلوک کے خلاف نہیں ہے ۔ (ابن عاشور: ۷؍۳۱۷)\nآیت میں ابراہیم علیہ السلام کا جو اسلوبِ بیان آیا ہے کیا اس میں والدین کے ساتھ حسنِ معاملہ اور اچھے سلوک کی مخالفت پائی جاتی ہے اس کی وضاحت کریں؟\nفَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ٧٦\nبات یہ ہے کہ محبت ہی عبادت کی اصل ہے لہذا اس میں شرک کرنا، اصلی شرک ہے جیسا کہ اللہ نے یہ بات امام الحُنفاء ابراہیم خلیل علیہ السلام کے قصے میں بیان فرمائی ہے چنانچہ فرمایا: (فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ) پھر جب ان پر رات کی تاریکی چھا گئی تو انہوں نے ایک ستارہ دیکھا اور کہا: یہ میرا رب ہےلیکن جب وہ ڈوب گیا توکہا : میں ڈوب جانے والوں سے محبت نہیں رکھتا۔یعنی ستارے کے رب ہونے کی تردید اس طرح کی کہ میں محبت نہیں رکھتا۔ (ابن تیمیہ:۳؍ ۳۴)\nمحبت عبادت کی اصل ہے جسے جاہلوں نے شرک کی اصل بنادیا۔اس بات کو آیت کریمہ کی مدد سے بیان کیجئے.\nقَالَ هَٰذَا رَبِّيۖ\nیعنی: ابراہیم علیہ السلام نے اپنے مخالفین کو حجت پیش کرتے اور سمجھاتے ہوئے بطور تنزّل (یعنی اپنے حقیقی موقف سے وقتی طور پر نیچے اترتے ہوئے)یہ بات کہی کہ ٹھیک ہے ،چلو مان لیایہ ستارہ میرا رب ہے ،اب آؤ ہم دیکھیں اور غور کریں کہ کیا یہ واقعی رب ہونے کا مستحق ہے ؟اور کیا ہمارے سامنے اس بات کی کوئی دلیل ہے ؟ کیونکہ کسی بھی عقل والے انسان کے لئے ایسی بات جائز وروانہیں کہ بغیر حجت اور واضح دلیل کے اپنی خواہش کو اپنا معبود بنالے ۔ (السعدی: ۲۶۲)\nستارے کے بارے میں ابراہیم علیہ السلام نے کہا کہ‘‘وہ ان کا رب ہے’’۔اس کی کیا وجہ ہے؟\nفَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ ٧٦\n(ٱلۡأٓفِلِينَ) یعنی: ڈوب جانے اورچھپ جانے والے سے مرادوہ چیز یا ہستی ہے جو اپنی عبادت کرنے والے کے سامنے سے اوجھل ہوجائے۔ (ابراہیم علیہ السلام نے فرمایاکہ :ایسے ڈوب جانے والے سے میں محبت نہیں کرتا) کیونکہ معبود کا ایسا ہونا ضروری ہے کہ وہ اپنے بندے اور عبادت کرنے والے کی مصلحتوں کا خیال رکھنے والا اور ضرورتوں کو پورا کرنے والاہو نیز بندے کے تمام معاملات کا انتظام وتدبیر اور بندوبست کرنے والاہو۔اس کے برخلاف جو ہستی ایسی ہو کہ زیادہ تر اوقات میں وہ غائب رہے ۔وہ کہاں سے اور کیسے عبادت کی مستحق ہوسکتی ہے ؟ایسی ہستی کو معبود بنانا،سب سے بڑی حماقت اور سب سے بڑا جھوٹ نہیں تو اور کیا ہوگا! (السعدی: ۲۶۲)\nجو ہستی اپنے عابد(عبادت کرنے والے،پجاری) سے چھپ جائے اور اوجھل ہوجائے۔وہ عبادت کی مستحق کیوں نہیں ہے؟\nقَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ٧٧\nانبیاء کرام علیہم السلام پابندی کے ساتھ اللہ تعالیٰ سے ایمان پر ثابت قدمی کی دعامانگتے رہتے تھے ۔خود ابراہیم علیہ السلام یہ کلمات کہا کرتے تھے : (وَاجْنُبْنِيْ وَ بَنِيَّ اَنْ نَّعْبُدَ الْاَصْنَامَ) (سورۂ ابراہیم :۳۵) یعنی:مجھے اور میری اولاد کو بت پرستی سے بچائے رکھ! (البغوی: ۲؍ ۴۱)\nانبیاء کرام علیہم السلام دین پر ثابت قدم رہنے کی سخت خواہش رکھتے تھے۔اس بات کی دلیل بیان کیجئے۔\nإِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ٧٩\nیقیناًمیں اپنی عبادتوں میں اس ذات کی طرف اپنا رخ کرتا ہوں جس نے آسمانوں اور زمین کو پیدا کیا ہے ،جو ذات لازوال اور دائمی ہے ، ہمیشہ باقی رہنے والی ہے، فنا ہونے والی نہیں ہے اور جوجِلاتی اورمارتی ہے۔میں اُن معبودانِ باطلہ کی طرف رخ نہیں کرتا جو خود فانی ہیں ،باقی رہنے والے نہیں ہیں ،جن کا انجام زوال ہے اور انہیں دوام وبقاء حاصل نہیں ہے اور وہ ایسے ہیں کہ نہ نقصان پہنچاسکتے ہیں نہ فائدہ۔ (الطبری: ۱۱؍۴۸۷)\nدوسروں کی عبادت کی بجائے صرف اللہ کی عبادت واجب ہونے کے کیا اسباب ہیں؟\nوَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ ٨١ ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ ٨٢\nیعنی: میں ۔لاچار وبے بس۔مُردوں سے کیوں کرڈروں؟ جبکہ تم شرک کرتے ہوئے بھی اس اللہ سے نہیں ڈرتے جو ہر چیزپر قدرت رکھتا ہے ....! (فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ) پس دونوں فریق میں اللہ کے عذاب سے امن وسلامتی کا زیادہ حقدار کون ہے؟ موحِّد (توحید پر قائم رہنے والا) یا مشرک؟ چنانچہ اس سوال پر اللہ تعالیٰ ان کے درمیان فیصلہ سناتے ہوئے فرماتا ہے: (ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ) جو لوگ ایمان لائے،اللہ کو مانااور اپنے ایمان کو ظلم سے آلودہ نہیں کیا یعنی شرک کی ملاوٹ نہیں کی تو امن اور سلامتی انہی کے لئے ہے۔ (القرطبی: ۸؍۴۴۴)\nاللہ سے زیادہ مُردوں سے ڈرنا، انتہائی جہالت ہے ۔اس بات کو آیت کی مدد سے واضح کیجئے\nwords\nجَنَّاندھیرا چھا گیا.\nالآفِلِينَغائب ہونے والے.\nأَفَلَغائب ہوگیا.\nحَنِيفًاشرک سے توحید کی طرف میلان."],[138,"§الأنعام\ndeeds\nخوب غور سے اس آیت کی تفسیرپڑھئے۔پھر اس سے تین فائدے بتائیے.\nتین ایسے شرعی مسائل کی تحدید کیجئے جن کا سمجھنا آپ کے لئے مشکل ہوگیا ہو،پھر کسی عالم سے مل کر ان کے جوابات پوچھئے اور ہر مشکل مسئلے میں یہی آپ کا طریق ہونا چاہئے ۔ یقیناً جتنا آپ کا علم ہوگا دنیا اور آخرت میں اتنی ہی آپ کو بلندی ملے گی.\nانبیاء کرام علیہم السلام کی تین صفات کا تعین کیجئے او ر ان میں انبیاء کی پیروی کیجئے.\nguid\nدنیا اور آخرت میں ہر خوف سے امان اسی میں ہے کہ اللہ سبحانہ وتعالیٰ کے لئے توحید کو خالص کیا جائے.\nاس زندگی میں انسان کے لئے سب سے بہترین عطیہ وتحفہ صراط مستقیم کی ہدایت ہے.\nاگر ۔بالفرض۔انبیاء کرام علیہم السلام سے شرک ہوجاتا تو ان کے اعمال بھی برباد ہوجاتے ۔توسوچئے ان سے کم مرتبہ والوں کا کیا معاملہ ہوگا!\nrefl\nوَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ\nابراہیم علیہ السلام نے ہماری کامل اطاعت کی ،اپنے رب کی توحید کو خالص اور بے غباررکھااور اللہ کے ساتھ شرک کرنے والی اپنی قوم کے دین کو چھوڑ کر ان سے علیحدگی اختیار کرلی ۔ان عظیم نیکیوں کے بدلے میں ہم نے ان پر یہ نوازشیں کیں کہ علیین میں ان کے درجے اور مرتبے کو بہت بلند کردیا ، دنیا میں بھی اجروثواب سے ان کا دامن بھردیااور انہیں ایسی اولاد بخشی جنہیں ہم نے نبوت کی خصوصیت سے نوازا،ایسی ذریت اور نسل دی جنہیں ہم نے اپنی طرف سے عزت وکرامت کا شرف اور تاج پہنایااور عمومی طور پر تمام دنیا جہاں کے لوگوں پر انہیں فضیلت اور برتری عطاکردی۔(الطبری: ۱۱؍۵۰۷)\nجو شخص اللہ کے واسطے کسی چیز کو چھوڑتا ہے ،اللہ تعالیٰ اسے اس سے بہتر بدلہ عطاکرتا ہے ۔اس بات کو آیت کی روشنی میں بیان کیجئے.\nوَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ\n(ہم نے علم و حجت کی بنا پر ابراہیم علیہ السلام کا درجہ بڑھا دیا) اس لئے کہ علم ایسی چیز ہے کہ اللہ تعالیٰ صاحبِ علم کو اس کی بدولت دوسرے بندوں کے مقابل درجات میں بلند کردیتا ہے ۔خاص طور سے وہ عالم جو عامل بھی ہو اور معلّم بھی ۔یعنی خود بھی عمل کرنے والا ہو اور دوسروں کو بھی اپنا علم سکھانے والا ہو ،ایسے علم والے شخص کو اللہ تعالیٰ اس کی حالت وتقاضے کے مطابق لوگوں کا امام بنادیتا ہے ۔اس کے کردار وعمل پر لوگوں کی نگاہیں ٹکی ہوتی ہیں، اس کے نقشِ قدم کی پیروی کی جاتی ہے ،اس کے نور سے روشنی حاصل کی جاتی ہے اور اس کے علم کی مدد سے زندگی کے راستے طے کئے جاتے ہیں ۔(وہ گھٹاٹوپ اندھیروں میں لوگوں کے لئے منارۂ نور اور مشعلِ راہ بن جاتا ہے۔) (السعدی:۲۶۳)\nابراہیم علیہ السلام کو ان کی قوم کے مقابل درجات میں بلند کئے جانے کا کیا سبب ہے؟\nنَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ ٨٣\nیعنی:ہم جس کے درجات بلند کرنا چاہتے ہیں اسے علم ومعرفت ،سوجھ بوجھ،شرف وفضیلت اور عقل وشعورسے نوازتے ہیں،جس طرح ہم نے ابراہیم ۔علیہ السلام۔کے درجات کو بلند کیا ،یہاں تک کہ وہ ہدایت یاب ہوگئے اور پھر توحید کے سلسلہ میں اپنی قوم پر حجت قائم کردی۔ (البغوی: ۲؍۴۱)\nبندے کے درجات ومراتب کس طرح بلند ہوتے ہیں؟\nوَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ٨٤\nیہ ابراہیم علیہ السلام کی جزاء تھی،ان کے عمل کا بدلہ تھا کہ جب وہ اپنی قوم سے الگ ہوگئے ، انہیں چھوڑدیا، ان کی بستی سے نکل گئے اور وطن سے ہجرت کرلی تاکہ دنیا کے کسی ایسے مقام کا راستہ لیں جہاں صرف اللہ کی عبادت کریں ۔اس وقت اللہ عزوجل نے انہیں ان کی صلبی(حقیقی) نیک اولاد کی شکل میں ان کی قوم اور خاندان کا بدل عطافرمادیا۔ تاکہ ان کے ذریعہ ابراہیم علیہ السلام کی آنکھیں ٹھنڈی ہوں ۔ (ابن کثیر :۲؍ ۱۴۷)\nابراہیم علیہ السلام کی اولاد اور بیٹے کس طرح ان کے حسنِ عمل کا بدلہ تھے؟\nوَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ٨٨\n(وَلَوۡ أَشۡرَكُواْ ) اگر وہ۔ذکر کردہ انبیاء کرام ۔شرک کربیٹھتے۔یعنی ۔یہ اگرچہ ناممکن اور محال بات ہے لیکن۔فرض کرلیں کہ اگر ایسا ہوتا (لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ) تونتیجہ میں ان کا سب کیا دھرا اور سارے اعمال برباد ہوجاتے کیونکہ شرک ایسا عمل ہے جو تمام اعمال کو برباد کردیتا ہے اور جہنم میں داخل کرنے کا ہی نہیں بلکہ اس میں ہمیشگی کا سبب بنتا ہے۔چنانچہ اللہ کے فرمان کے مطابق اگر اللہ کے یہ برگزیدہ اور بہترین بندے یعنی انبیاء کرام بھی شرک کرتے۔ جبکہ ان پاکباز نفوس سے ایسا ہرگز نہیں ہوسکتا تھا۔تو ان کے اعمال بھی ضائع ہوجاتے ۔ اب جب انبیاء کے بارے میں اللہ کا یہ فیصلہ ہے تو ان کے علاوہ دوسرے لوگوں کے اعمال شرک کی وجہ سے برباد ہوجانے کے زیادہ مستحق ہیں۔ (السعدی:۲۶۴)\nشرک اعمال کوبرباد کردیتا ہے خواہ وہ بڑے بڑے بزرگوں اور صالحین سے ہی کیوں نہ سرزد ہو ۔ اس بات کو آیت کی روشنی میں واضح کیجئے.\nوَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ ٨٨\nیعنی۔ اگر یہ انبیاء کرام بھی۔میرے علاوہ دوسرے کی عبادت کرلیتے تو ان کے سارے کئے کرائے پر پانی پھر جاتا ،ساری نیکیاں اور قربانیاں ضائع ہو جاتیں، لیکن میں (اللہ)نے انہیں بچالیا ۔ (القرطبی: ۸؍ ۴۵۱)\nاس شخص کی جزاء کیا ہے جو اللہ کے ساتھ شرک کرے جبکہ اس کے نیک اعمال بھی ہیں؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ\nیعنی : اے رسول کریم! آپ ان برگزیدہ انبیاء کے پیچھے چلئے ،ان کی ملت کی پیروی کیجئے۔ نبی صلی اللہ علیہ وسلم نے اللہ کے اس حکم کی پوری تعمیل کی چنانچہ آپ نے اپنے سے پہلے انبیاء اور رسولوں کا طریقہ اور ان کی سیرت اختیارفرمائی اور الگ الگ رسولوں کی تمام خوبیاں،کمالات اور خصوصیات اپنی ذاتِ بابرکات میں اکٹھاکرلیں۔اس طرح آپ کے دامنِ اقدس میں تمام فضیلتیں اور خصوصیتیں سمٹ گئیں اور آپ کی ذات وشخصیت مخلوق میں سب سے کامل اور سب سے جامع شخصیت بن گئی۔اور آپ رسولوں کے سردار اور متقیوں کے امام ہوگئے۔صلوات اللہ وسلامہ علیہ وعلیہم أجمعین۔ (السعدی: ۲۶۴)\nیہ آیت کس طرح ہمارے رسولِ کریم صلی اللہ علیہ وسلم کی دیگر رسولوں پر افضلیت کو ثابت کرتی ہے؟\nwords\nيَلبِسُواوہ اسے ملا دیں.\nوَاجتَبَينَاهُمہم نے ان کو چن لیا.\nاقتَدِهاس کی اتباع کرو."],[139,"§الأنعام\ndeeds\nآپ پر یا امت پر قرآن کریم کی جو برکتیں ہیں ان میں سے کوئی تین ذکر کیجئے.\nآج نمازوں کے لئے بالکل اول وقت میں جائیے اور جیسے اللہ نے آپ کو حکم دیا ہے اسی طرح انہیں ان کے ارکان اور شروط کے ساتھ ادا کیجئے.\nاپنے آپ کا محاسبہ اور سرزنش کرنے کے لئے سکون سے بیٹھئے ۔اوراللہ کے روبرو پیشی کے دن کو سامنے رکھ کر اپنی بڑی بڑی نیکیوں اوربڑے بڑے گناہوں کا موازنہ کیجئے جو آپ نے اپنی پوری عمر میں کئے ہیں.\nguid\nغور کیجئے کہ اللہ تعالیٰ اپنے بندوں کے معاملے میں کتنا بردبار ہے ! کہ وہ بندوں کی جانب سے خود اپنی ذات سے متعلق دل آزار باتیں سنتا ہے۔اور اپنے رسولوں اور اولیاء کے جھٹلانے کو بھی سنتا ہے،اس کے باوجود انہیں فوری عذاب نہیں دیتاتاکہ انہیں برائیوں سے پھر جانے اور ایمان کی جانب پلٹ آنے کا موقع مل سکے.\nنصیحت حاصل کرنے کی نیت سے اور غوروفکرکے ارادہ سے کتاب اللہ کی طرف متوجہ ہوجائیے تاکہ آپ کو اس کی خیر وبرکت حاصل ہوسکے.\nآپ اس دنیا میں جو کچھ بھی جمع کررہے ہیں وہ سب فنا ہوجائیگا اور آپ تنِ تنہا اللہ تعالیٰ کے سامنے پیش ہونگے.\nrefl\nوَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ\n(وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ ) انہوں نے اللہ کی ویسی قدر نہیں کی جیسی قدر کرنی چاہئے تھی۔مطلب: اللہ تعالیٰ اپنے بندوں پر جو لطف وکرم اور رحمت و مہربانی کا برتاؤ کرتاہے ،اس بارے میں ان لوگوں نے اللہ کوکما حقہ نہیں پہچانا ۔اسی لئے انہوں نے رسولوں کی بعثت اور آسمانی کتابوں کے اتارنے کا انکار کیا، اور ایسا کرنے والے اور ایسی بات کہنے والے یہود تھے۔اس کی دلیل اس کے بعد والی آیت ہے، اوردراصل انہوں نے یہ بات محض اس لئے کہی تھی کہ بڑھ چڑھ کرمحمد صلی اللہ علیہ وسلم کی نبوت کا انکار کریں۔ (ابن جُزی: ۱؍ ۲۷۸)\nاللہ عزوجل کی قدرجیسی ہونی چاہیے ویسی قدرکی کیا نشانی ہے؟\nوَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ\nوالبی رحمۃ اللہ علیہ کی ایک روایت میں عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ انہوں نے فرمایا: یہ فرمان کافروں کے بارے میں ہے اور رہا مومن توجو اس بات کا یقین کرتاہے کہ ‘‘اللہ ہر چیز پرقادر ہے’’ تو وہ اللہ کی قدر کرتا ہے جیسی اس کی قدر ہونی چاہئے۔ (ابن تیمیہ: ۳؍ ۳۵)\nحق کے مطابق کون اللہ کی قدر کرتا ہے؟\nوَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ\nآیت میں جس بات کو “عظیم ظلم” کہا گیا ہے وہ ہے اللہ پر بہتان باندھنا اور اپنی طرف وحی کئے جانے کا جھوٹا دعویٰ کرنا، بالکل ایسے ہی ظالم وہ لوگ بھی ہیں جو دین کی صحیح سمجھ اور سنتوں سے روگردانی کرتے ہیں۔اور امت کے سلف یعنی صحابہ وتابعین جن سنتوں اور طریقوں پر عمل پیرا تھے ان سے پہلو تہی کرتے ہیں اورکہتے ہیں کہ: ‘‘ہمارے دل میں یہ بات سوجھی ہے ا ہمارے دل نے ہمیں ایسی ایسی خبر دی ہے ۔ پھر ان کے دلوں میں جو بھی باتیں آتیں اور جن افکار وخیالات کا غلبہ ہوتا انہی کے مطابق فیصلے اور عمل کرتے ہیں۔ اس طرح وہ اپنے ان خود ساختہ افکار وخیالات کو اپنا کر ان کے مقابلے میں اللہ کی شریعت کے کلی احکام واصول سے بے نیازہوجاتے ہیں۔ اورکہتے یہ ہیں کہ شریعت کے عام احکام کے ذریعہ تو صرف نادان،کم عقل اور عام لوگوں کے فیصلے کئے جائیں گے ۔رہے اولیاء کرام اور اہلِ خصوص تو یہ لوگ قرآن وسنت کی ان نصوص کے محتاج نہیں ہیں ۔ (القرطبی: ۸؍۴۵۸)\nکیا دلوں میں پیدا ہونے والے خیالات اور خوابوں کو شریعت کا ایک مصدرسمجھنا ، اللہ تعالیٰ پر جھوٹ باندھنے میں شامل ہے؟\nوَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ\nآیت میں مذکور باتیں اور دعوے سب سے بڑا ظلم اس لئے ہیں کہ ان میں جھوٹ اور بہتان ہے ۔نیز ان باتوں کے نتیجہ میں دین ومذہب میں (ان کے اصولی احکام اور فروعی مسائل میں) تبدیلی اور رد وبدل ہوجاتا ہے اور پھران چیزوں کو اللہ کی طرف منسوب کرنایہ سب ایسی چیز ہے جو سب سے زیادہ فسادانگیز اور نقصان دہ ہے ۔اس لئے مذکورہ باتیں کہنے والا شخص مخلوق میں سب سے بڑا ظالم ہے۔ (السعدی: ۲۶۵)\nاللہ تعالیٰ پر جھوٹ باندھنے والا شخص مخلوق میں سب سے ظالم کیوں ہے؟\nوَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ ٩٣\n(وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ) اور فرشتے اپنے ہاتھ بڑھائے ہوئے ہوتے ہیں۔ عذاب دینے اورمارنے کے لئے ۔ فرشتے اپنے ہاتھوں سے ان کے چہروں اور پیٹھوں پر چوٹ لگاتے اور مارتے ہیں ۔ اور دوسرا معنی یہ بیان کیا گیا ہے کہ: ان کی جانوں کو نکالنے کے لئے فرشتے ہاتھ بڑھاتے ہیں ۔ (أَخۡرِجُوٓاْ) لاؤ ،نکالو۔یعنی فرشتے کہتے ہیں: لاؤ ،نکال باہر کرو۔ (أَنفُسَكُمُۖ) یعنی اپنی جانوں کو اپنے جسموں سے نہ چاہتے ہوئے اور زبردستی نکال باہر کرو۔ کراہت کے ساتھ اس لئے کہ بندۂ مومن کی روح اپنے رب سے ملاقات کے لئے خوشی خوشی تیار ہوتی ہے جبکہ کافر کی روح اسے ناپسند کرتی ہے ۔ آیت کے شرطیہ جملے۔ اگر آپ دیکھتے۔ کا جوابِ شرط محذوف ہے ۔شرط اور جوابِ شرط کا مطلب یہ ہوتا ہے کہ : اگر آپ ان ظالموں کو موت کے وقت مذکورہ حالت میں دیکھ لیتے تو عجیب منظر پاتے۔ (البغوی: ۲؍ ۴۷)\nموت کے وقت بندۂ مومن کی روح نکلنے اور کافر کی روح نکلنے میں کیا فرق ہے؟\nوَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ\nتمام لوگ۔بشمول فرشتے،انبیاء وصالحین۔ اللہ کے بندے اور غلام ہیں ۔ اللہ تعالیٰ سب کا مالک ہے اور وہی ان سب کی عبادت کا مستحق ہے لہذا لوگوں کا اللہ کی عبادت میں شرک کرنااور اللہ کے بعض غلاموں اور بندوں کے لئے عبادت کے کاموں کو کرنا دراصل ان بندوں اور غلاموں کو خالق ومالک اور آقائے حقیقی کا مقام دیناہے چنانچہ قیامت کے روز اس سنگین جرم پر ان کی سرزنش کی جائیگی اور دھتکارا جائیگا۔ (السعدی: ۲۶۵)\nمذکورہ آیت کے تناظر میں قیامت کے روز اولیاء اور صالحین کی عبادت کرنے والوں کی حسرت وندامت کا حال بیان کیجئے.\nوَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ\nالجميع عبيد لله، والله مالكهم والمستحق لعبادتهم، فشركهم في العبادة وصرفها لبعض العبيد تنزيل لهم منزلة الخالق المالك، فيوبخون يوم القيامة. السعدي:۲۶۵.\nمن خلال الآية: بيّن حسرة من يعبدون الصالحين يوم القيامة وندامتهم.\nwords\nغَمَرَاتِھولناکیاں.\nخَوَّلنَاكُمہم نے تمہیں أموال دنیا کا مالک بنادیا.\nتَقَطَّعَ بَينَكُمتمہارے رابطے منقطع ہو گئے."],[140,"§الأنعام\ndeeds\nکسی زندہ کی ایک مثال دیجئے جسے اللہ نے مردے سے نکالا ہو اورکسی مردہ کی مثال دیجئے جسے اللہ نے زندہ سے نکالا ہو۔ اور اللہ تعالیٰ کی قدرت پر غوروفکر کیجئے.\nعبادات کے سلسلہ میں قمری کیلنڈر کی اہمیت کے بارے میں پڑھئےاور قمری مہینوں کے نام یاد کیجئے تاکہ آپ صحیح وقت پر عبادات انجام دے سکیں.\nرات میں جلدی سویا کیجئے اس لئے کہ یہ فطرت بھی ہے اور سنتِ رسول صلی اللہ علیہ وسلم بھی.\nguid\nجو قرآن کی خاطر اپنے دل اور عقل کو کھول دے وہی اس کی آیات کے مقاصد کو سمجھنے کا حقدار ہے برخلاف اس کے جو قرآن کے لئے اپنے دل اورعقل کو بند رکھے.\nہم جو غذائیں کھاتے ہیں یقیناًوہ اس کی حقدار ہیں کہ ہم اس میں اللہ سبحانہ وتعالیٰ کی عمدہ اور انوکھی کاریگری پر غور کریں اور اس پر بھی کہ ان کے مزے اور رنگوں میں بھی کیسا فرق ہوتا ہے!\nاگر آپ کسی کو اللہ کی طرف کوئی جھوٹ منسوب کرتا ہوا سنیں تواپنے رب کی پاکی بیان کیجئے اور ظالموں وملحدوں کی باتوں سے اس کو پاک وصاف قرار دیجئے.\nrefl\nإِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ٩٥\nیہاں اللہ تعالیٰ نے اپنی کاریگری اور بناوٹ کے چند عجائب گنوائے ہیں ،جن میں سے معمولی سے معمولی اور کمتر سے کمتر چیز کو بھی بنانے سے ان کے معبودانِ باطلہ عاجز وقاصر ہیں۔ (القرطبی: ۸؍۴۶۵)\nآیت کریمہ میں اللہ نے اپنی کاریگری کے عجائب گنائے ہیں ،اس کی حکمت کیا ہے؟\nيُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ٩٥ فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ\nاللہ نے بیان فرمایا ہے کہ وہ مختلف اور متضاد اشیاء کو پیدا کرنے پر پوری قدرت رکھتا ہے جو اس کی بڑائی اور عظمت کے کمال کی دلیل ہے۔ (ابن کثیر: ۲؍ ۱۵۰)\nمتضاد(ایک دوسرے کی ضد) چیزوں کو پیدا کرنے پر اللہ کی قدرت کس بات کا ثبوت دیتی ہے؟\nوَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٩٧\nیہ آیت اور اس قسم کی دوسری آیات اس بات پردلالت کرتی ہیں کہ ستاروں کی نقل وحرکت،ان کی رفتار اور ان کے محل ومقام کا علم حاصل کرناشریعت میں جائز ہے،جسے ‘‘علم التسییر’’ یعنی ستاروں کی حرکت اور مقامات کا علم کہاجاتا ہے۔شرعاً اس کی اجازت اس لئے ہے کہ اس کے بغیر راستوں اور اوقات کی پوری معلومات اور صحیح رہنمائی نہیں مل سکتی اور اس علم کے بغیر یہ کام نہیں کیا جاسکتا۔ (السعدی: ۲۶۶)\nعلمِ نجوم یعنی ستاروں کے علم میں کیا سیکھنا جائز ومباح ہے اور کیاحرام ہے؟\nقَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ ٩٨\nیعنی: ان آیات کو ہم نے ان لوگوں کے سامنے بالکل صاف اور واضح کردیا ہے جو علم اور معرفت والے ہیں ،اس لئے کہ یہی لوگ ہیں جن کی طرف اللہ کے خطاب کا رخ ہے اور انہی سے جواب بھی طلب کیا گیا ہے ۔برخلاف ان لوگوں کے جو جاہل اور جفاکار ہیں اور اللہ کی آیتوں سے نیز رسولوں کے لائے ہوئے علم سے اعراض کرنے والے ہیں۔تو ان لوگوں کے سامنے اللہ تعالیٰ کا واضح بیان کوئی فائدہ نہیں دیتا اور آیتوں کی تفصیل ان کے شک وشبہ کو دور نہیں کرتی،نیز ان کی وضاحت ان کی مشکل کو آسان نہیں کرتی۔ (السعدی: ۲۶۶)\nآیتوں کو تفصیل کے ساتھ بیان کرنا صرف اہل علم کے ساتھ کیوں خاص کیا گیا ہے؟\nوَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ\nکھجور کے گچھوں (خوشوں) کے ساتھ جھکے اور لٹکے ہوئے ہونے کا ذکر بطور خاص کیا گیا ہے اس لئے کہ اللہ کی قدرت کا ذِکر کرنا اور اس کی نعمتوں کا احسان جتانااوراس کی مہربانی وکرم فرمائی بیان کرنا دراصل آیت کے مقاصد میں شامل ہے اور جو نعمت استعمال کرنے والے سے قریب ہواس میں احسان وکرم کا پہلو زیادہ ہوتا ہے۔ (القرطبی: ۸؍۴۷۲)\nاس آیت میں کھجور کے جھکے ہوئے گچھوں کو خاص طور پر کیوں ذکر کیا گیا ہے؟\nٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٩٩\nعبرت کی نگاہ سے دیکھیں،غوروفکر سے خالی صرف معائنہ کی نظر سے نہیں۔ (القرطبی: ۸؍۴۷۲)\nآیت کریمہ میں جس نظر سے دیکھنے کا حکم دیا گیا ہے وہ کون سی نظر ہے؟\nإِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٩٩\n(مومنوں کے لئے ان چیزوں میں نشانیاں ہیں) اس لئے کہ مومنوں کے پاس ایمان کی جو نعمت ہے وہ انہیں ایمان کے تقاضوں اور لوازمات پر عمل کرنے کی رغبت دلاتی ہے ۔ ان ایمانی تقاضوں میں یہ بھی شامل ہے کہ بندۂ مومن اللہ کی آیتوں میں غور وفکر کرے اور ان کے مرادی معنی کا استنباط کرے۔ اور یہ آیتیں عقلی،فطری اور شرعی اعتبار سے جس چیز پر دلالت کرتی ہیں انہیں معلوم کرے اور سمجھے۔ (السعدی: ۲۶۷)\nاللہ کی آیتوں کے بابت دوسروں کے علاوہ صرف مومنوں کو فائدہ پہنچانے والی ہونے کا خصوصی ذکر کیوں کیا گیا؟\nwords\nتُؤفَكُونَتم حق سے موڑتے ہو.\nقِنوَانٌ دَانِيَةٌٹہنیاں جنہیں قریب سے پکڑا جاسکتا ہو.\nوَيَنعِهِاور اس کے پکنے کے قریب.\nوَخَرَقُواجھوٹ گھڑا؛ اللہ سبحانہ و تعالیٰ پر."],[141,"§الأنعام\ndeeds\nجو موضوع آپ کے ذہن میں آ رہا ہو اس سے متعلق آیتیں اکٹھی کیجئے ،پھر ان کی تفسیر پڑھئے یا ان کے معانی دریافت کیجئے.\nیہ دعا مانگئے: ‘‘اَللّٰہُمَّ اِنِّىْ أَعُوْذُبِكَ أَنْ يُزَیَّنَ لِیْ سُوءُ عَمَلِیْ’’۔اے اللہ !میں اس بات سے تیری پناہ چاہتا ہوں کہ میرے برے اعمال میرے لئے مزین کردیئے جائیں.\nیہ دعا مانگتے رہئے: ‘‘اَللّٰہُمَّ !یَا مُقَلِّبَ القُلُوْبِ! ثَبِّتْ قَلْبِیْ عَلیٰ دِیْنِكَ’’۔اے اللہ! اے دلوں کے پھیرنے والے! میرے دل کو اپنے دین پر ثابت قدم رکھ.\nguid\nوحی الٰہی یعنی کتاب اللہ اور سنت صحیحہ پر عمل پیرا رہئے ۔ان کا حق کسی اور کو مت دیجئے.\nدعوتی میدان میں ایسا کچھ نہ کیجئے کہ آپ کا مخالف، اہل سنت والجماعت کی دعوت اور منہج سے متنفر ہوجائے بلکہ حکمت کا دامن تھامے رکھئے بیشک یہ داعی الی اللہ کے بڑے ہتھیاروں میں سے ہے.\nدین سے رخ موڑنے والے کو اس طرح بھی سزا دی جاسکتی ہے کہ اسے ہمیشہ کے لئے ہدایت اور دین سے محروم کردیا جائے چنانچہ آپ متنبہ وچوکنا رہئے.\nrefl\nذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ١٠٢\n(ٱللَّهُ رَبُّكُمۡۖ) ذکر کردہ صفات والا یہی اللہ تمہار ا پالنہارو رب ہے۔یعنی: وہی حقیقی معبود اور عبادت کے لائق ہے اور وہی بندوں کی جانب سے انتہائی عاجزی اور انتہائی محبت کا مستحق ہے ۔وہی تو وہ رب ہے جس نے اپنی نعمتوں کے ذریعہ تمام مخلوق کو اپنے دامنِ ربوبیت میں پالا،ان کی ہر ضرورت کا انتظام فرمایا اور انہیں مختلف قسم کی مصیبتوں اور تکلیفوں سے بچائے رکھا۔ (السعدی: ۲۶۸)\nکلمہ ‘‘رب’’ کے کیا معنی ہیں؟اور اس کے معنی پر کیا نتیجہ اور معنی مرتب ہوتاہے؟\nوَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ١٠٢\nتمام اشیاء پر اللہ تعالیٰ کی وکالت مخلوق کی آپسی وکالت کی طرح نہیں ہے کیونکہ مخلوق کی وکالت حقیقت میں نیابت اور نمائندگی ہے جس میں وکیل اپنے مؤکل کا تابع ہوتا ہے ۔ رہی باری تبارک وتعالیٰ کی ذات تواس کی وکالت خود اس کی ذات کی طرف سے ہوتی ہے اور خود اپنی ذات کے لئے ہی ہوتی ہے ۔اللہ کی وکالت کامل علم اور حسنِ تدبیر وانتظام پر مشتمل ہوتی ہے جس میں احسان بھی ہوتا ہے اور انصاف بھی ۔ لہذا کسی کے لئے ممکن نہیں ہے کہ اللہ تعالیٰ پر استدراک کرے یعنی اس کے کسی کام میں کمی اور خامی کی تلافی کرے ۔نہ وہ اللہ کی تخلیق میں کوئی خلل اور خرابی دیکھ سکتاہے اور نہ ہی اس کی تدبیرمیں کوئی نقص اور عیب پاسکتا ہے۔ (السعدی: ۲۶۸)\nاشیاء پر اللہ کے وکیل ہونے اور انسانوں کے وکیل ہونے کے درمیان کیا فرق ہے؟\nلَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ١٠٣\nآیت میں ‘‘اِدراک’’ کی نفی کی گئی ہے جس کا مطلب اِحاطہ کرنے کی نفی کرناہے جیسا کہ اکثر علماء نے کہا ہے ۔ محض دیدار کرنے کی نفی نہیں کی گئی ہے ۔ اس لئے کہ ناموجودچیزدکھائی نہیں دیتی اور اس کا دکھائی نہ دینااس کی تعریف نہیں ہے ۔ یعنی معدوم چیز کا ناقابلِ دید ہونا کوئی خوبی نہیں ہےکیونکہ اگر ایسا ہوتا تو ہر ناموجود چیز قابل تعریف ہوتی۔خوبی اور تعریف کی بات تو یہ ہے کہ اس کا احاطہ اور گھیراؤ نہ کیا جاسکے خواہ اسے دیکھا جاسکتا ہوجیسا کہ اللہ کے بارے میں معلومات کا احاطہ نہیں کیا جاسکتااگرچہ اللہ کے بارے میں علم حاصل ہوتا ہے۔لہذا جس طرح یہ بات واضح ہے کہ اللہ کی ذات وصفات کا علم تو حاصل ہوسکتا ہے لیکن کسی کا علم اللہ کی ذات وصفات کو محیط نہیں ہوسکتا۔بالکل اسی طرح اللہ کا دیدار تو ہوسکتا ہے لیکن اس کے دیدار میں احاطہ نہیں ہوسکتا۔ (ابن تیمیہ: ۳؍ ۷۸۔۷۹)\nآپ آیت سے کیسے ثابت کریں گے کہ قیامت کے دن اللہ کا دیدارثابت ہے اور آیت سے اس کی نفی نہیں ہوتی.\nٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ١٠٦\nیعنی: اپنے ذہن و خیال کومشرکین میں مشغول نہ رکھیں بلکہ اللہ کی عبادت میں مصروف رہیں۔ (القرطبی: ۸؍۴۹۰)\nدنیا کی زندگی میں دل کو کس چیز میں مشغول رکھنا بہتر ہے.\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nاللہ سبحانہ نے مومنوں کو مشرکین کے بتوں کو برابھلاکہنے سے منع کیا ہے اس لئے کہ اللہ تعالیٰ خوب جانتا ہے کہ جب مومنین انہیں گالی دیں گے تو اس سے کفار بھڑک اٹھیں گے نیز کفر وانکار میں اور بڑھ جائیں گے ۔ (القرطبی: ۸؍۴۹۱)\nاللہ تعالیٰ نے مومنوں کو کافروں کے معبودوں اور بتوں کو گالی دینے سے کیوں روکا ہے؟\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nاس آیت کریمہ میں اس شرعی قاعدہ کی دلیل ہے کہ :وسائل وذرائع کو انہی چیزوں سے جوڑکر دیکھا جائیگا جن چیزوں اور نتیجوں تک یہ پہنچاتے ہیں لہذا حرام چیزوں تک پہنچانے والے وسیلے حرام ہوں گے ۔ اگرچہ بذات خود یہ حلال ہی ہوں لیکن اگر اس سے شر وفساد پیداہوتے ہیں تو وہ حلال ذریعے بھی حرام ہوں گے۔ (السعدی: ۲۶۹)\nعلماء نے مذکورہ آیت سے ایک عظیم شرعی قاعدہ نکالا ہے ،وہ کیا ہے؟\nوَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ\nجب ایسا ہوکہ کافروں کو طاقت و قوت حاصل ہواوراندیشہ ہوکہ اسلام کوبدنام کیاجائے گا اور برابھلاکہاجائےگا یا نبی صلی اللہ علیہ وسلم کو اور اللہ عزوجل کو سب وشتم کریں گے تو کسی مسلمان کے لئے جائز نہیں کہ وہ کافروں کے دین کو ،ان کی صلیبوں اور بتوں کو سب وشتم کا نشانہ بنائے اور نہ ہی ایسی کوئی بات کہے جس کے نتیجہ میں اس برائی کا دروازہ کھلے یا ایسی کسی حرکت کا راستہ بنے۔ (ابن عطیہ: ۲؍ ۳۳۲)\nکس وقت مصلحت یہ تقاضا کرتی ہے کہ کافروں کے معبودوں کو برابھلا نہ کہا جائے؟\nwords\nنُصَرِّفُہم بیان کرتے ہیں.\nدَرَستَتم نے تعلیم حاصل کی.\nعَدوًادشمنی کرتے ہوئے.\nيَعمَهُونَوہ حیران و سرگرداں پھرتے ہیں."],[142,"§الأنعام\ndeeds\nاللہ سبحانہ وتعالیٰ سےبکثرت یہ دعا مانگئے کہ وہ آپ کو ہدایت دے اور دین پر ثابت بھی رکھے ۔کیونکہ ہدایت صرف اللہ تعالیٰ کے ہاتھ میں ہے.\nانسانی شیاطین اور انبیاء کے دشمن کیسا سوچتے ہیں اور ان کے کیا نظریات ہیں۔یہ جاننے کے لئے یہود کی عالمی منصوبہ بندی پر مشتمل کوئی کتاب پڑھئے.\nجائز اور حرام ذبح کے احکام کو جاننے کے لئے اس موضوع پر کوئی کتاب پڑھئے، یا کوئی درس سنئے .\nguid\nچکنی چپڑی اور لچھے دار باتیں باطل پرستوں کا ایک طریق کار ہے۔ ورنہ درحقیقت اِن باتوں کے پیچھے صرف فسادہوتا ہے.\nجو دل اللہ پر ایمان سے خالی ہوتے ہیں وہی اہل شہوات اور شبہات کی باتوں پر دھیان دیتے ہیں.\nاکثریت میں ہونا،حق پر ہونے کی دلیل نہیں ہے.\nrefl\nوَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ\nقتادہ ،مجاہد اور حسن رحمہم اللہ تینوں حضرات کہتے ہیں:جس طرح جنوں میں شیاطین ہوتے ہیں ویسے ہی انسانوں میں بھی شیاطین ہوتے ہیں۔اور مالک بن دینار رحمہ اللہ نے کہاکہ:انسانوں کے شیاطین جنوں کے شیاطین سے زیادہ خطرناک ہوتے ہیں وہ اس طرح سے کہ میں جب اللہ کی پناہ لیتا ہوں تو شیطان مجھ سے دور بھاگ جاتا ہے لیکن انسانی شیطان میرے پاس آتا ہے اورکھلے عام مجھے گناہوں کی طرف کھینچ لے جاتا ہے۔ (البغوی: ۲؍ ۵۶)\nکیا جنوں کی طرح انسانوں میں بھی شیاطین ہوتے ہیں ؟اور ان میں کس کا خطرہ زیادہ بڑا ہوتا ہے؟\nيُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ\nیعنی: وہ جن باطل چیزوں کی طرف دعوت دیتے ہیں ،ان چیزوں کو ایک دوسرے کے سامنے سجاسنوارکراور خوبصورت بناکر پیش کرتے ہیں اور وہ اپنی ان باتوں کو خوشنما عبارتوں سے آراستہ کرکے انہیں بہترین شکل وصورت اور دلنشین انداز واسلوب میں ڈھالتے ہیں تاکہ بیوقوف لوگ ان چکنی چپڑی گمراہ کن باتوں سے فریب کھاجائیں، بھولے بھالے لوگ انہیں مان لیں اور ان کے پیچھے چل پڑیں، جو نہ چیزوں کی اصلیت کو سمجھ پاتے ہیں اور نہ صحیح معنی ومطلب کو جان پاتے ہیں بلکہ انہیں تو بس سنہری الفاظ اور زریں عبارتیں بھاتی ہیں، چنانچہ وہ حق کو باطل سمجھ بیٹھتے ہیں اور باطل کو حق مان لیتے ہیں۔ (السعدی: ۲۶۹۔۲۷۰)\nاہل باطل اپنی باتوں کو سجانے سنوارنے کا اہتمام کیوں کرتے ہیں؟\nوَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ\nاللہ تعالیٰ نے یہ بات بتائی ہے کہ رسولوں کے دشمنوں کی جو باتیں ہوتی ہیں ان کی طرف دھیان دینے والے ،ان کی طرف جھکنے اور مائل ہونے والے لوگ وہی ہیں جو آخرت پر ایمان نہیں رکھتے۔ اس سے معلوم ہوا کہ رسولوں کی مخالفت اور آخرت پر ایمان نہ رکھنا دونوں میں چولی دامن کا ساتھ ہے ۔ پس جس کسی کا آخرت پر ایمان ویقین نہیں رہا وہ رسولوں کے دشمنوں کی باتوں میں آگیا اور رسولوں کا مخالف ہوگیا، جیسا کہ اس امت اور دیگر امتوں کے مختلف قسموں کے کفار اور منافقین میں یہ بات پائی جاتی ہے ۔ (ابن تیمیہ: ۳؍ ۸۹۔۹۰)\nرسولوں کی مخالفت اور آخرت پر ایمان کو ترک کرنا یہ دونوں لازم وملزوم ہیں ۔اس بات کو بیان کیجئے.\nوَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١١٥\n(وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ) آپ کے رب کی بات سچائی اور انصاف کے اعتبار سے کامل ہے۔معلوم ہوا کہ اللہ تعالیٰ نے رسولوں کو علم اور انصاف کے ساتھ بھیجا ہے، لہٰذا جو شخص علم اور عدل کے اعتبار سے جتنا کامل ہوگا وہ رسولوں کی لائی ہوئی تعلیمات اور شریعت سے اتنا ہی زیادہ قریب ہوگا۔ (ابن تیمیہ: ۳؍ ۳۹)\nوہ کون سی چیزیں ہیں جو رسولوں کی لائی ہوئی تعلیمات سے آپ کے قریب ہونے کا معیار مقرر کرتی ہیں ؟\nوَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ١١٦\nگمراہ لوگوں کی اس اکثریت کی وجہ یہ ہے کہ حق اور ہدایت کے لئے کئی اوصاف کا ہونا ضروری ہے :عقل سلیم کا ہونا،شریف نفس کا ہونا، نفع و نقصان کی سمجھ کا ہونا،خواہشات نفس پر حق کواور اسی طرح لذت وشہوت پر ہدایت اور سیدھے راستے کو ترجیح دینے کے جذبہ اور جرأت کا ہونا، اور لوگوں کے لئے خیر وبھلائی کو پسند کرنا۔ ان صفات میں سے اگر کسی ایک میں بھی خلل آجائے تو جس قدر ان صفات میں خلل پڑیگا اسی کے مطابق آدمی کے اندر گمراہی کو راستہ ملے گا۔ (ابن عاشور: ۸؍۲۵)\nدنیا میں گمراہ لوگوں کے زیادہ ہونے کا کیا سبب ہے؟\nوَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ١١٦\nیہ آیت کریمہ اس بات پر دلیل ہے کہ کسی گروہ کی تعدادکابہت زیادہ ہوناان کے حق پر ہونے کی دلیل نہیں بنتی، اور نہ ہی کسی بھی طریقے پر چلنے والوں کی تعداد کی کمی ان کے ناحق ہونے کی دلیل ہے۔بلکہ سچائی اس کے برخلاف ہے۔اس لئے کہ اہل حق تعداد میں بہت تھوڑے ہوتے ہیں لیکن اللہ کے یہاں مقام ومرتبے میں اور اجر وثواب میں سب سے آگے ہوتے ہیں۔ (السعدی: ۲۷۰)\nآج لوگوں میں اکثریت پر ایمان لانے یعنی کثرت تعداد کی بات ماننے کا اور اکثریت کو اقلیت پر ترجیح دینے کارجحان عام ہے۔ اس بارے میں شریعت کا نقطۂنظر کیا ہے؟\nفَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ ١١٨\nاللہ کے فرمان: (إِن كُنتُم بَِٔايَٰتِهِۦ مُؤۡمِنِينَ) “اگر تم اللہ کی آیتوں پر ایمان رکھتے ہو” کا مطلب ہے:اگر تم اس کے احکامات اور ہدایات کو اختیار کرتے ہو۔ کیونکہ آیتوں پرایمان رکھنے کا یہ تقاضا بھی ہے کہ انہیں قبول کرلے اور ان کاپابند بن جائے۔ (ابن عطیہ: ۲؍ ۳۳۸)\nجن جانوروں پر ذبح کرتے وقت اللہ کا نام لیا گیا ہو،ان کے کھانے کا حکم ایمان کے ذکر کے ساتھ کیوں ختم کیا گیا ہے؟\nwords\nقُبُلًاآمنے سامنے.\nغُرُورًادھوکا.\nوَلِتَصغَىتاکہ تم مائل ہو جاؤ.\nوَلِيَقتَرِفُواتاکہ وہ کمائیں.\nيَخرُصُونَوہ بدگمانی کرتے ہیں/ جھوٹ بولتے ہیں."],[143,"§الأنعام\ndeeds\nحلال غذا کھانے سے پہلے اللہ کا نام لیجئے.\nچوری چھپے کئے جانے والے ان گناہوں پرآج ہی اپنا محاسبہ کیجئے جنہیں صرف اللہ تعالیٰ ہی جان سکتا ہے.\nجن چیزوں پر اللہ کا نام نہ لیا گیا ہو انہیں کھانے کی ممانعت پر ایک پیغام بھیجئے.\nguid\nگناہ کھلے ہوئے ہوں یا چھپے ہوئے ،دل کے اعمال میں سے ہوں یا اعضاء کے ذریعہ انجام دئے جانے والے کاموں میں سے، انہیں چھوڑنا واجب ہے.\nہمیشہ حلال اور پاکیزہ غذا ہی استعمال کیجئے ۔اس طور پر کہ اسی جانور کا گوشت کھائیں جسے ذبح کرتے وقت اللہ کا نام لیا گیا ہو، انہیں نہ کھائیں جن پر اللہ کا نام نہ لیا گیا ہو.\nشرک موت اور تاریکی ہے جبکہ ایمان زندگی اور روشنی ہے.\nrefl\nوَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ\nیہ آیت کریمہ اس بات پر دلالت کرتی ہے کہ تمام اشیاء اور کھانوں میں اصل ‘‘مباح اور جائز ہونا’’ہے۔اور یہ کہ جب تک شریعت کسی چیز کو حرام نہیں ٹھہراتی وہ اپنی اصل مباح اور جائز ہونے پر باقی رہتی ہے، چنانچہ اللہ تعالیٰ نے جس چیز کا حکم بیان نہیں فرمایا ہے وہ حلال ہے ،اس لئے کہ جو کچھ حرام ہے اللہ نے اس کی تفصیل بیان فرمادی ہے۔اس کا یہ مطلب ہواکہ اللہ نے جس چیز کی تفصیل بیان نہیں کی ہے وہ حرام نہیں ہے۔ (السعدی: ۲۷۱)\nمذکورہ آیت اس شرعی قاعدے پر کس طرح دلیل بنتی ہے کہ اشیاء میں اصل اباحت اورجوازہے؟\nوَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ١١٩\nکسی کی نفرت کی بنیاد پر ،توکسی کے لئے یہ جائز نہیں کہ وہ اللہ کی شریعت کو چھوڑکر اسی کی اتباع کرے جو اسے اچھی لگے ،پھر دوسروں کو بھی اس کا حکم دے اور اسی کو اپنا دین بنالے ،بلکہ یہ چیز صرف اللہ کی ہدایت کی بنیاد پر ہونی چاہئے۔اور اللہ کی ہدایت اس کی شریعت جس پر اس نے اپنے رسول کو کاربند فرمایا ہے ۔ لہٰذا جو کوئی شریعت محمدی علیٰ صاحبہا الصلوٰۃ والسلام سے ہٹ کر کسی پسند اور ناپسند یا محبت اور نفرت کی بناپر اپنی چاہت کی اتباع کرتا ہے تو وہ اللہ کی ہدایت کے بغیر خواہشات نفس کی پیروی کرتا ہے۔ (ابن تیمیہ: ۳؍ ۹۶)\nاللہ تعالیٰ کی جانب سے ملنے والے علم کے بغیر خواہشات کی اتباع کرنا کتنا خطرناک ہے؟بیان کیجئے.\nوَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ١١٩\nپھر اللہ عزوجل نے ان لوگوں کی گمراہی کے بارے میں بتایا کہ ان کی گمراہی بدترین شکل کی ہے ۔ وہ اس طرح کہ ان کی گمراہی غور وفکر اور سمجھ بوجھ کی بنیاد پر نہیں ہے بلکہ خواہشات نفس کے پیچھے پڑنے کی وجہ سے ہے۔ اور ’’بغیر علم‘‘ کا مطلب ہے بلا سوچے سمجھے۔ (ابن عطیہ: ۲؍ ۳۳۹)\nگمراہی کی بدترین صورت کیا ہے۔؟\nوَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ١٢٠\nبندہ کھلے اور چھپے گناہوں کو اسی وقت پوری طرح چھوڑسکتا ہے جب وہ ان گناہوں کی جانکاری حاصل کرلے۔لہذا انہیں تلاش کرنادل اور جسمانی اعضاء وجوارح دونوں کے گناہوں کی معرفت حاصل کرنامکلف بندے پر فرض ہے، جبکہ حال یہ ہے کہ بہت سے لوگوں کو گناہوں کا علم نہیں ہوتا ہے ،خاص طور پر دل کے گناہ جیسے :کبروگھمنڈ ، انانیت اورریاکاری جیسے گناہ چھپے رہ جاتے ہیں اور اسے پتہ نہیں چلتا،یہاں تک کہ بندہ ان میں سے بہت سے گناہوں یا کچھ گناہوں کا خوب ارتکاب کرتا ہے اور اسے اس کااحساس تک نہیں رہتا۔ یہ دراصل علم اور فہم وبصیرت سے محرومی کا نتیجہ ہوتا ہے۔ (السعدی: ۲۷۱)\nظاہری اور باطنی گناہوں اور نافرمانیوں سے بچنے کے لئے آدمی کو سب سے پہلے کیا کرنا ضروری ہے؟\nوَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ١٢٠\n(وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ) “اور تم ظاہری گناہوں کو بھی چھوڑدو اور باطنی گناہوں کو بھی” ۔ یہاں لفظ اور تعبیر ایسی ہے جس کے عمومی معنی میں ہر قسم کے گناہ آجاتے ہیں اس لئے کہ جتنے بھی گناہ ہیں سب کے سب یا تو باطنی یعنی چھپے ہوئے ہیں یاپھر ظاہری یعنی کھلے ہوئے ہیں۔نیز اس کا ایک معنی یہ بھی بیان کیا گیا ہے کہ ظاہر سے مراد اعمال ہیں اور باطن سے مراد عقیدہ ہے۔ (ابن جُزی: ۱؍ ۲۸۴)\nاس آیت میں اختصار اور عموم دونوں ہے۔اس کی وضاحت کیجئے.\nوَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ\nیہ آیت کریمہ اس بات پر دلالت کرتی ہے کہ دلوں میں جو کشف اور الہامات ہوتے ہیں جو صوفیاء اور ان جیسے لوگوں کے یہاں کثرت سے واقع ہوتے ہیں ۔ یہ کشف والہامات محض الہام ہونے کی بناپر بذات خود اس بات کی دلیل نہیں ہیں کہ وہ حق ہیں، اور اس وقت تک ان کی تصدیق نہیں کی جائیگی جب تک انہیں کتاب اللہ اورسنت رسول اللہ صلی اللہ علیہ وسلم کی کسوٹی پر جانچ نہ لیا جائے، چنانچہ اگر قرآن وسنت ان الہامات وغیرہ کے قابل قبول ہونے کی گواہی دیں تو وہ قبول کئے جائیں گے، اور اگر ان کے مخالف ہوں تو یہ بلا تردد رد کردئیے جائیں گے۔اور اگر قرآن وحدیث سے موافقت یا مخالفت کچھ بھی معلوم نہ ہوسکے تو پھر توقّف اور خاموشی اختیار کی جائیگی۔نہ انہیں سچا اور درست مانا جائیگا اور نہ ہی جھوٹ اور غلط قرار دیا جائیگا۔اس کی وجہ یہ ہے کہ وحی اور الہام رحمن کی جانب سے بھی ہوتا ہے اور شیطان کی طرف سے بھی ۔لہٰذا بہت ضروری ہے کہ رحمانی اور شیطانی الہام کے درمیان فرق اور تمیز کرلی جائے ۔دراصل ان دونوں الہاموں میں فرق نہ کرنے یا نہ کرپانے کی بناپر لوگوں کو اتنی ٹھوکریں لگتی ہیں اور اس قدر غلطیاں اور گمراہیاں پیدا ہوتی ہیں جس کا حساب وشمار اللہ کے سوا کوئی نہیں کر سکتا۔ (السعدی: ۲۷۱)\nمذکورہ آیت کے ذریعہ آپ کس طرح اس شخص کی تردید کریں گے جو الہامات اورکشف کو کتاب وسنت پر پیش کئے بغیرمان لیتا ہے اور ان کی تصدیق کرتا ہے؟\nوَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ ١٢٣\n(وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ) “اور اسی طرح ہم نے ہر بستی میں وہاں کے بڑے لوگوں کو ہی جرائم کا مرتکب بنایا”۔ یعنی: جس طرح ہم نے مکہ میں اس کے سرداروں اور رئیسوں کو جرائم میں لگادیا تاکہ وہ اپنے شہر میں مکروفریب پھیلائیں ۔ٹھیک اسی طرح ہم نے ہر بستی میں کیا ہے ۔ آیت میں صرف’’اکابر‘‘یعنی بڑے لوگوں اور سرداروں کا ذکر کیا گیا ہے اس لئے کہ دوسرے لوگ تو ان کے پیچھے چلنے والے اور تابع ہوتے ہیں۔ (ابن جُزی: ۱؍ ۲۸۴)\nآیت میں دوسروں کو چھوڑکرصرف بڑے لوگوں کے ذکر پر کیوں اکتفاء کیا گیا ہے؟\nwords\nصَغَارٌذلت /رسوائی."],[144,"§الأنعام\ndeeds\nاللہ سے دعا کیجئے کہ وہ حق کے لئے آپ کا سینہ کھول دے ،چاہے حق کہیں بھی ہو.\nیاد کیجئے کہ اللہ تعالیٰ نے آپ کو ہدایت کی نعمت سے نوازا ہے ،اس طور پر کہ اسلام کے لئے آپ کا سینہ کھول دیا، اگر وہ نہ چاہتا تو آپ اس نعمت سے محروم رہتے.\nجنوں کے شر سے اللہ تعالیٰ کی پناہ مانگئے.\nguid\nہدایت اللہ سبحانہ وتعالیٰ کے ہاتھ میں ہے، چنانچہ آپ ہدایت اس کے مالک سے ہی مانگئے.\nاللہ کا انکار کرنے والے دلوں میں ہر طرح کے شر سے بھری ہوئی شہوتیں اور شبہے ڈال دئے جاتے ہیں، اور وہ شیطان کی تفریح گاہ ہوتے ہیں.\nبکثرت نیک اعمال کیجئے کہ یہی اللہ کی ولایت کے حصول کا سبب ہیں.\nrefl\nفَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ\nاللہ تعالیٰ اپنے بندوں کے سامنے ،بندے کی سعادت اور ہدایت کی علامت بیان کرتے ہوئے فرماتا ہے کہ: جس شخص کا سینہ اسلام کے لئے کھل جائے ... یعنی اسلام کو ماننے کے لئے کشادہ ہوجاتا ہے ... تب وہ ایمان کی روشنی سے منور ہوجاتا ہے ،اور یقین کی رونق سے جی اٹھتا ہے، چنانچہ اس کا نفس ایمان پر مطمئن ہوجاتا ہے ،نیکی سے محبت کرنے لگتا ہے ۔اتناہی نہیں بلکہ اس کا نفس نیک کاموں کو بوجھ سمجھنے كے بجائے لذت محسوس کرتے ہوئے بخوشی کرتا ہے۔ تو یہ کیفیت اس بات کی علامت ہے کہ اللہ نے اس بندے کو ہدایت عطاکردی ہے ساتھ ہی اس کی توفیق کا انعام بھی دیا ہے اور سب سے بہترو درست راستے پر چلنے کا احسان بھی کیا ہے۔ (السعدی: ۲۷۲)\nہدایت ملنے کی کیا نشانی ہے جسے آدمی خود اپنے نفس میں محسوس کرتا ہے؟\nوَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ\nیعنی: اس شخص کی ایسی حالت وکیفیت ہوتی ہے جیسے وہ آسمان کی بلندی میں چڑھ جانا چاہتا ہو لیکن یہ اس کے لئے ممکن نہیں ہوتا،بالکل اسی طرح ایمان لانا اس کے لئے مشکل ہوجاتا ہے ۔ (ابن جزی: ۱؍ ۲۸۵)\nگمراہ آدمی اور آسمان میں چڑھنے والے شخص کے درمیان مشابہت کی کیا وجہ ہے؟\nوَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ\nایک کافر ایمان سے جو نفرت کرتا ہے اور اسے اختیار کرنے میں جو بوجھ اور مشقت محسوس کرتا ہے،اللہ تعالیٰ نے اسے اس شخص کی حالت سے مشابہت دی ہے جو اپنے اوپر ایسا بوجھ اور ذمہ داری لا دلیتا ہے جسے نبھانے کی اسے طاقت نہیں ہوتی۔بالکل اسی طرح جیسے آسمان میں چڑھنا آدمی کی طاقت سے باہر ہے۔ (القرطبی: ۹؍۲۵)\nجس شخص پر گمراہی لکھ دی گئی ہواس کے لئے ایمان کو قبول کرنا مشکل بلکہ ناممکن ہوتا ہے ۔اس بات کی وضاحت کیجئے.\nلَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ ١٢٧\nمراد جنت ہے ۔جنت کو ‘‘دارالسلام’’ یعنی سلامتی کا گھر کہا گیا ہے، کیونکہ جو کوئی اس میں داخل ہوگا وہ تمام بلاؤں اورمصیبتوں سے محفوظ ہوجائیگا۔ (البغوی: ۲؍ ۶۳)\n‘‘دارالسلام’’ سے کیا مراد ہے ؟اور اسے یہ نام کیوں دیا گیا ہے؟\nوَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ١٢٩\nہماری سنت اور قانون ایسے ہی ہے کہ ہم ایک ظالم شخص کو دوسرے ظالم شخص کا دوست بنادیتے ہیں جو اسے شرپر آمادہ کرتا ہے اور برائی کے لئے اکساتا ہے ،نیز خیر میں بے رغبتی پیدا کرتا ہے ،نیکی اور اچھائی سے نفرت دلاتا ہے ۔یہ اللہ تعالیٰ کی طرف سے دی جانے والی سزاؤں میں سے ایک بہت بڑی سزا ہے ،جس کا اثربہت برا اور خطرہ بہت بڑا ہوتا ہے، اورقصور خود ظالم کا ہی ہوتا ہے کیونکہ وہ خود ہی ہے جس نے اپنے آپ کو نقصان میں ڈالا اور اپنے ہی خلاف جرم کا ارتکاب کرکے خود اپنے پیروں پر کلہاڑی ماری ہے ۔ (وَ مَا رَبُّكَ بِظَلَّامٍ لِّلْعَبِيْدِ ۰۰۴۶) (سورۂ حم السجدۃ: ۴۶) اور آپ کا رب بندوں پرقطعاً ظلم نہیں کرتا۔ ایک ظالم پر دوسرے ظالم کو مسلط کرنے کی ایک شکل یہ بھی ہے کہ جب بندوں کا ظلم وستم اور شروفساد بہت بڑھ جاتا ہے اور وہ اپنے اوپر واجب حقوق کی ادائیگی روک دیتے ہیں تو ان پر ظالموں کو مسلط کردیا جاتا ہے جو انہیں سنگین عذاب اور سخت تکلیف میں مبتلا کرتے ہیں۔ اور وہ ظلم وجور اور زورزبردستی کرکے ان سے اس کا کئی گنا زیادہ حصہ چھین لیتے ہیں جو انہوں نے اللہ کے حقوق اور بندوں کے حقوق کو روکا اور ہڑپ کیا ہوتاہے۔(السعدی: ۲۷۳)\nبعض ظالموں پر دوسرے ظالموں کو مسلط کئے جانے کی حالتوں میں سے دوحالتوں کوبیان کیجئے.\nوَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ١٢٩\nیہ ظالم آدمی کے لئے کھلی دھمکی ہے کہ اگر وہ اپنے ظلم سے باز نہیں آتا تو بدلے میں اللہ تعالیٰ اس پر دوسرے ظالم کو مسلط کردیگا۔ فضیل بن عیاض رحمۃ اللہ علیہ فرماتے ہیں:جب تم یہ دیکھو کہ ایک ظالم دوسرے ظالم کو دکھ اور سزا دے رہا ہے تو ذرا ٹھہرکر اس پر عبرت کی نگاہ ڈالو۔ (القرطبی: ۹؍۳۰)\nاللہ تعالیٰ ظالم کو دنیا میں کس چیز کے ذریعہ سزا دیتا ہے؟\nيَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ١٣٠\nاس کا مطلب ہے :یقیناًتمہارے پاس تمہارے درمیان سے اللہ کے پیغمبر اور رسول علیہم السلام آئے تھے جو قطعی اور فیصلہ کن دلیلوں کے ذریعہ تمہارے دین اور طریقے کی خرابیاں اجاگر کرتے رہے اور اس کے غلط ہونے سے تمہیں آگاہ کرتے رہے ،نیز جس راستے اور منہج پر تم اڑے ہوئے تھے یہ پیغمبر اس کے برے انجام کی دھمکی سے تمہیں ڈراتے رہے تھے ۔لیکن تم نے ان کی باتوں کو قبول نہیں کیا ،نہ نصیحت حاصل کی اور نہ ہی عبرت پکڑی۔ (الطبری: ۱۲؍ ۱۲۰)\nسزادینے سے پہلے خلاف ورزیوں کو یاد دلانا قرآن کا منہج اورطریقہ ہے ۔آیت کے تناظرمیں اس کی وضاحت کیجئے.\nwords\nحَرَجًابہت سخت تنگی.\nيَصَّعَّدُ فِي السَّمَاءِوہ فضائی طبقات میں چڑھتا ہو.\nالرِّجسَعذاب.\nدَارُ السَّلاَمِامن و سلامتی کا گھر۔ جنت.\nاستَمتَعَاس نے فائدہ اٹھایا."]])